var e={common:{cancel:`Cancelar`,"count.files":{one:`{count} archivo`,many:`{count} de archivos`,other:`{count} archivos`},"list.and":`{first} y {second}`,"list.then":`{first}, luego {second}`,"list.comma":`{first}, {second}`,"list.semicolon":`{first}; {second}`,"bank.slot":`Ranura {letter}`,"bank.slot:acc":`la ranura {letter}`,"bank.slot:gen":`de la ranura {letter}`,"bank.slot:dat":`a la ranura {letter}`,"bank.slot:loc":`en la ranura {letter}`,"bank.slot:ins":`La ranura {letter}`,"bank.recovery":`Ranura de recuperación {letter}`,"bank.recovery:acc":`la ranura de recuperación {letter}`,"bank.recovery:gen":`de la ranura de recuperación {letter}`,"bank.recovery:dat":`a la ranura de recuperación {letter}`,"bank.recovery:loc":`en la ranura de recuperación {letter}`,"bank.recovery:ins":`La ranura de recuperación {letter}`,"bank.slotInSentence":`ranura {letter}`,"bank.slotInSentence:acc":`la ranura {letter}`,"bank.slotInSentence:gen":`de la ranura {letter}`,"bank.slotInSentence:dat":`a la ranura {letter}`,"bank.slotInSentence:loc":`en la ranura {letter}`,"bank.slotInSentence:ins":`La ranura {letter}`,"bank.recoveryInSentence":`ranura de recuperación {letter}`,"bank.recoveryInSentence:acc":`la ranura de recuperación {letter}`,"bank.recoveryInSentence:gen":`de la ranura de recuperación {letter}`,"bank.recoveryInSentence:dat":`a la ranura de recuperación {letter}`,"bank.recoveryInSentence:loc":`en la ranura de recuperación {letter}`,"bank.recoveryInSentence:ins":`La ranura de recuperación {letter}`},app:{title:`Herramientas de firmware para Seek Thermal`,"header.cameraSelected":`Cámara seleccionada`,"header.noCamera":`Ninguna cámara seleccionada`,"header.usbUnavailable":`USB no disponible`,"header.github":`Las herramientas en GitHub`,"header.tabs":`Pestañas`,"tab.info":`Información`,"tab.preserve":`Volcar y descifrar 0.x/1.x`,"tab.v4":`Volcar y descifrar 4.x/Nano`,"tab.decrypt":`Descifrar archivo/ranura`,"tab.slots":`Gestionar ranuras de firmware`,documentTitle:`Firmware de Seek Thermal — {tab} (WebUSB)`,"theme.label":`Tema oscuro`,"theme.followsSystem":`Sigue el ajuste claro u oscuro de tu sistema`,"theme.chosenDiffers":`Elegido aquí. Vuelve a cambiarlo para seguir el ajuste de tu sistema.`,"theme.chosenSame":`Elegido aquí; ahora coincide con el ajuste de tu sistema`,"language.label":`Idioma`,"intro.info":"Lee la cámara conectada igual que `seek-fw info`: su firmware, la familia con la que responde, cómo arranca, sus claves y todas sus ranuras. Te dice cuál de las otras pestañas le corresponde y explica con palabras sencillas para qué sirve cada pestaña. **En esta pestaña no se escribe nada en la flash.**","intro.preserve":`Para cámaras **0.x y 1.x** (las compilaciones de 2014 y 2016). Hace una copia **completa** de la flash de 4 MB de la cámara, incluidas las partes a las que no llega un volcado normal, y después deja la cámara exactamente como estaba. Hace una copia de seguridad de lo que puede leer, aplica brevemente un parche al firmware para poder leer el resto, lo vuelca todo, restaura el original y lo comprueba. Todo se ejecuta localmente en tu navegador. **Dos de los pasos escriben en la flash**, y cada uno te lo pregunta antes.`,"intro.v4":`Hace una copia de solo lectura de la flash SPI de 4 MB de una cámara **4.x o Nano** por WebUSB y descifra las imágenes de firmware que encuentre. Todo se ejecuta localmente en tu navegador: no se sube nada a ningún sitio. **Solo lectura:** esta pestaña no envía ningún comando de escritura, borrado, subida, confirmación ni reinicio de la flash. Una cámara de otra línea de firmware se rechaza antes de leer nada.`,"intro.decrypt":`Descifra firmware que ya tienes, en este equipo: un volcado completo de la flash o una ranura de firmware de 64 KB. **No se usa ninguna cámara**, así que funciona sin nada conectado y en navegadores sin acceso USB. El archivo se lee aquí y nunca se sube.`,"intro.slots":`Lee las tres ranuras de firmware de la cámara (ranura A, ranura B y ranura de recuperación R) y muestra lo que contiene cada una, desde cuál arranca la cámara y qué puede hacer esta compilación con ella, junto al firmware en ejecución y las claves del dispositivo. Todo se ejecuta localmente en tu navegador. **Esta pestaña escribe en la flash:** puede escribir una ranura a partir de una imagen descifrada o de bytes sin procesar, y pregunta antes de cada escritura.`,"support.ios.title":`**WebUSB no está disponible en iOS ni en iPadOS,** así que este dispositivo no puede leer la flash de una cámara.`,"support.ios.body":`Safari no lo implementa, y todos los navegadores de iOS están obligados a usar WebKit, así que aquí Chrome y Firefox tampoco pueden ofrecerlo. No hay ninguna opción ni extensión que lo cambie. Para volcar una cámara, usa un equipo de escritorio o un teléfono Android con un cable USB-OTG.`,"support.noWebUsb.title":`**Este navegador no puede acceder a dispositivos USB.**`,"support.noWebUsb.body":`WebUSB está disponible en Chrome, Edge, Opera y otros navegadores basados en Chromium, en Windows, macOS, Linux y Android. Firefox y Safari han decidido no implementarlo.`,"support.noWebUsb.insecure":`Además, esta página no se sirve por una conexión segura, y eso ya basta para bloquear WebUSB.`,"support.insecure.title":`**Conexión no segura.** Aquí WebUSB está desactivado.`,"support.insecure.body":"Abre esta página por HTTPS o desde `http://localhost`. Una dirección de red local sin más, como `http://192.168.1.10:8000`, no sirve.","support.offlineStillWorks":`Puedes seguir usando la pestaña **{tab}**: funciona solo con un archivo que eliges y no necesita acceso USB.`,"support.ready":`**Listo.** Conecta tu cámara Seek y pulsa *{connect}*.`,"support.fileProtocol":`Se ha abierto como archivo local, así que el navegador no recordará el dispositivo entre recargas. No pasa nada.`,unlockNote:`Nota: {note}.`,"connect.title":`Conectar`,"connect.actions":`Acciones del dispositivo`,"connect.connect":`Conectar dispositivo`,"connect.change":`Cambiar dispositivo`,"connect.test":`Probar conexión`,"connect.forget":`Olvidar dispositivo`,"connect.vendorNote":"Se ofrece cualquier dispositivo Seek Thermal (proveedor USB `{vendor}`): Compact, Compact PRO, Nano, etc. Elige el tuyo en el selector de dispositivos del navegador.","platform.title":`Notas por plataforma`,"platform.macos":`Funciona directamente en Chrome, Edge o cualquier navegador basado en Chromium. Sin instalar controladores y sin permisos de administrador. Antes, cierra cualquier otro programa que ya se esté comunicando con la cámara: solo un proceso puede usar la interfaz USB a la vez.`,"platform.linux.access":`Da a tu usuario acceso al dispositivo y luego desconéctalo y vuelve a conectarlo:`,"platform.linux.sandbox":"Las versiones Snap y Flatpak de Chromium suelen estar aisladas de los dispositivos USB; la versión `.deb` o `.rpm` es la fiable.","platform.windows":"Windows necesita que el controlador WinUSB esté asignado a la cámara antes de que cualquier navegador pueda llegar a ella. Usa <zadig>Zadig</zadig>: *Options → List All Devices*, luego elige en la lista desplegable la entrada con el nombre de tu cámara (por ejemplo, `CompactPRO FF`), elige **WinUSB** como controlador y haz clic en Replace Driver. Si tu cámara aparece más de una vez, elige la entrada marcada *(Interface 0)*. Esto quita el dispositivo al software del fabricante hasta que lo reviertas en el Administrador de dispositivos (*Desinstalar el dispositivo → Eliminar el controlador*, y luego vuelve a conectarlo).","platform.android":`Funciona en Chrome para Android con un cable USB-OTG, siempre que el teléfono pueda alimentar la cámara por el bus USB. Android da acceso USB con su propio diálogo de permiso. La descarga llega a tu carpeta Descargas como cualquier otro archivo.`,"platform.ios.name":`iPhone y iPad`,"platform.ios.cannot":`**No puede leer una cámara**, y esto no va a cambiar. Safari no implementa WebUSB, y en iOS y iPadOS todos los navegadores, incluidos Chrome y Firefox, están obligados a usar WebKit, así que ninguno ofrece la API. No hay ninguna opción, extensión ni app que lo evite. Para volcar, usa un equipo de escritorio o un teléfono Android.`,"platform.ios.decrypt":`El descifrador opcional sí funciona aquí: descifrar un volcado que ya tienes no necesita acceso USB, así que puedes hacerlo desde un iPhone o un iPad, o desde Firefox y Safari en un equipo de escritorio.`},core:{"unlock.powerCycleNote":`la cámara sigue desbloqueada hasta que se apague y se vuelva a encender, y otras herramientas pueden leerla mal hasta entonces; apágala y vuelve a encenderla antes de usarlas`,"boot.rule":`{first} primero, luego {second}, luego {last}`,"boot.verdict.notRead":`no se leyó`,"boot.verdict.checkKeyUnnamed":`no se pudo comprobar: no se identificó la clave con la que su bootloader comprueba una ranura`,"boot.cfg0NotRead":`no se leyó la palabra de configuración de arranque (cfg[0]), así que no se sabe qué ranura usará el próximo arranque`,"boot.select.unknown":`la palabra de configuración de arranque es {word}, así que el bootloader prueba primero {first:acc}, pero {bank:acc} {verdict}, así que no se sabe qué ranura arranca`,"boot.select.first":`la palabra de configuración de arranque es {word}, así que el bootloader prueba primero {first:acc}, y esta contiene una imagen que el bootloader acepta`,"boot.select.second":`la palabra de configuración de arranque es {word}, así que el bootloader prueba primero {first:acc}; {first:acc} no contiene ninguna imagen que el bootloader acepte, así que toma {second:acc}`,"boot.select.lastBoots":`la palabra de configuración de arranque es {word}, así que el bootloader prueba primero {first:acc}; ni {first:acc} ni {second:acc} contienen una imagen que el bootloader acepte, así que arranca {last:acc}, que no comprueba`,"boot.select.lastTakes":`la palabra de configuración de arranque es {word}, así que el bootloader prueba primero {first:acc}; ni {first:acc} ni {second:acc} contienen una imagen que el bootloader acepte, así que toma {last:acc}, que no comprueba`,"boot.bootsNow":`{bank:ins} es la ranura desde la que arranca ahora la cámara`,"boot.bootedNow":`arranque actual`,"boot.notBooted":`no es la de arranque`,"boot.unknownWhy.checkKeyUnnamed":`en esta lectura no se identificó la clave con la que su bootloader comprueba una ranura`,"boot.unknownWhy.noKeyTable":`no se leyó la tabla de claves del bootloader, así que no se pueden nombrar las claves que prueba`,"fpsBoot.boots":`La cámara arranca desde {bank:acc}. {why}.`,"fpsBoot.holdsOne":`{bank}: contiene un parche de velocidad de fotogramas, pero no arranca, así que el parche no tiene efecto.`,"fpsBoot.holdsTwo":`Contienen parches de velocidad de fotogramas, pero ninguna arranca, así que los parches no tienen efecto: {banks}.`,"fpsBoot.wouldNotRun":`Aplicar el parche {target:dat} no haría que arrancara, porque la cámara arranca desde {bank:acc}.`,"fpsBoot.patchRunning":`Aplica el parche también {bank:dat} (la ranura que arranca): eso es lo que hace que el parche de velocidad de fotogramas tenga efecto.`,"fpsBoot.cannotPatch":`{bank}: no se le puede aplicar el parche aquí ({reason}), así que un parche de velocidad de fotogramas en otra ranura no tiene efecto en esta cámara.`,"backup.bank.notInPlan":`{name} (no está en el plan de esta compilación: el zip lo indica)`,"backup.bank.unsupported":`{name} (esta compilación no puede leerla, {reason}: el zip lo indica)`,"backup.bank.empty":`{name} (vacía, todos los bytes 0xFF: el zip lo indica, y la escritura no sobrescribe ningún firmware)`,"backup.bank.unread":`{name} (la lectura de las ranuras no llegó a ella: el zip indica si la lectura previa a la escritura llega)`,"backup.bank.noKey":`{name} (tal como está almacenada; ninguna clave recuperada en esta lectura la abre, así que no hay archivo descifrado)`,"backup.bank.decrypted":`{name} (tal como está almacenada, y descifrada)`,"backup.plan.one":`Antes de escribir nada, se vuelve a leer esta ranura y se guarda en un zip con una nota de lo que es cada archivo ({file}): {banks}.`,"backup.plan.many":`Antes de escribir nada, se vuelven a leer estas ranuras y se guardan en un zip con una nota de lo que es cada archivo ({file}): {banks}.`,"staging.detail.keyACiphertext":`cifrados para que el dispositivo los almacene con la clave que contiene la ranura de arranque`,"staging.detail.slotKeystreamCiphertext":`cifrados con la clave de transferencia propia de la imagen (bloque de claves 0); la cámara los almacena con la clave propia de la ranura`,"staging.detail.plain":`sin cifrar, sin ningún cifrado`,"staging.detail.keyAKeystream":`la imagen 1.3.0.8 FF tal como la transfiere la app del fabricante (XOR clave A); la compilación de 16 Hz la almacena con la clave B, no estos bytes`,"staging.detail.verbatim":`literales: los bytes exactamente como se dieron`,"copy.source.noRead":`sin lectura`,"copy.source.notInPlan":`{name:acc} no está en el plan de esta compilación`,"copy.source.notRead":`no se leyó {name:acc} ({reason}), así que no hay imagen que copiar`,"copy.source.empty":`{name:acc} está vacía: no hay imagen que copiar`,"copy.source.foreign":`{name:acc} no contiene ninguna imagen de firmware que esta lectura reconozca, así que no hay nada que copiar`,"copy.source.noKey":`ninguna clave recuperada en esta lectura abre {name:acc}, así que no hay imagen descifrada que copiar`,"copy.from":`{name} en {address}, tal como la descifró la lectura de las ranuras`,"copy.fromVersion":`{name} en {address}, firmware {version}, tal como la descifró la lectura de las ranuras`,"copy.note":`La imagen es {name:gen}, tal como la descifró la lectura de las ranuras: {size} B, sha256 {sha256}.`,"copy.noteVersion":`La imagen es {name:gen}, tal como la descifró la lectura de las ranuras: firmware {version}, {size} B, sha256 {sha256}.`,"restore.where":`{name:acc} de la copia de seguridad (en {address})`,"restore.from":`{where}, en la copia de seguridad completa de la flash {file}`,"restore.fromVersion":`{where}, en la copia de seguridad completa de la flash {file}, firmware {version}`,"restore.kind.flash-file":`una imagen de flash de 4 MB`,"restore.kind.preserve-run":`un archivo de ejecución de Preserve`,"restore.kind.dump":`un zip de «Volcar y descifrar 4.x/Nano»`,"restore.kind.all-selectors":`un zip de «Volcar todos los selectores»`,"restore.decryptedTo.image":`una imagen`,"restore.decryptedTo.firmware":`el firmware {version}`,"restore.note.image":`La imagen es {where} en {file}, {kind}: sha256 almacenado {stored}, descifrada como {decrypted} de {size} B (sha256 {sha256}).`,"restore.note.imageEntry":`La imagen es {where} en {file}, {kind} (su {entry}): sha256 almacenado {stored}, descifrada como {decrypted} de {size} B (sha256 {sha256}).`,"restore.note.readBack":`Después de la escritura, la ranura releída se compara con los bytes de la ranura que almacena la copia de seguridad.`,"restore.note.sameCamera":`El bloque de identidad de la copia de seguridad nombra esta cámara (número de serie {serial}).`,"restore.note.sameBytes":`{name:ins} ya contiene los bytes que almacena la copia de seguridad: la escritura vuelve a poner la misma imagen.`,"restore.warn.otherCamera":`Esta copia de seguridad parece de otra cámara: su bloque de identidad nombra el número de serie {theirs}, y esta cámara es {camera}. Solo se escribe la imagen {name:gen}; nada de la identidad ni de la calibración de esa cámara.`,"restore.warn.noIdentity":`Esta copia de seguridad no tiene bloque de identidad en {address}, así que no se puede saber de qué cámara se leyó.`,"restore.warn.serialNotRead":`No se leyó el número de serie de la cámara, así que la copia de seguridad (número de serie {serial}) no se puede comparar con ella.`,"restore.warn.otherFirmware":`{where} contiene el firmware {version}, y la cámara ejecuta {camera}: la restauración pone otro firmware en la ranura.`,"restore.readBack.notCompared":`{bank:ins} no se releyó, así que no se compara con la copia de seguridad.`,"restore.readBack.equal":`{bank:ins} se relee byte a byte tal como la almacena la copia de seguridad.`,"restore.readBack.differs":`{bank}: al releerla, difiere de los bytes que almacena la copia de seguridad en {count} B (el primero en {offset}).`,"keys.derived.same":`{key:acc}, que se obtiene {bank:gen}, con la que arrancó la cámara`,"keys.derived.holds":`{key:acc} (la clave de almacenamiento), que se obtiene {bank:gen}, con la que arrancó la cámara y que contiene {holds:acc}`,"keys.derived.sameUnnamed":`{key:acc}, que se obtiene de la ranura de arranque`,"keys.derived.holdsUnnamed":`{key:acc} (la clave de almacenamiento), que se obtiene de la ranura de arranque, que contiene {holds:acc}`,"keys.ffVendor.staged":`la imagen 1.3.0.8 FF (16 Hz) tal como la transfiere la app del fabricante: la imagen XOR su propio bloque de claves 0 (clave A), con la ventana de cabecera literal, a cualquier ranura; no se usan las claves de esta cámara`,"keys.ffVendor.stored":`clave B: la cámara vuelve a cifrar los datos recibidos con el bloque de claves 1 y almacena la imagen con esa clave`,"keys.imageBlock0.staged":`la imagen con su propio bloque de claves 0 (que se encuentra en la imagen por su valor), a cualquier ranura; no se usan las claves de esta cámara`,"keys.imageBlock0.storedUnnamed":`la clave con la que su bootloader comprueba una ranura (no identificada en esta lectura); la cámara vuelve a cifrar con ella los datos recibidos`,"keys.imageBlock0.stored":`{key:acc}, la clave con la que su bootloader comprueba una ranura; la cámara vuelve a cifrar con ella los datos recibidos`,"notes.ffBootUntested":`UNTESTED (sin probar): no se ha leído de ninguna cámara un bootloader de la compilación FF de 16 Hz, así que no se sabe si la ranura escrita arranca. Con el bootloader 0.9.0.0, una forma anterior de esta imagen arrancó desde la ranura de recuperación R; esta forma no lo hará, porque ese bootloader arranca la ranura de recuperación R tal como está almacenada, sin decodificarla.`,"write.ff.otherVersion":`La imagen FF de 16 Hz se envía en la forma que solo lee la compilación {version} de 16 Hz. Esta cámara escribe una ranura sin comprobar la imagen (así lo dice el código fuente de su firmware, y así lo hizo una Compact 1.3.0.0 cuando se probó), así que se espera que escriba los bytes tal como se envían: la ranura contendrá entonces la imagen en una forma con la que esta cámara no puede arrancar.`,"write.ff.untested":`{untested} Nada de lo que hay aquí afirma que la cámara arranque con ella.`,"write.ff.runsFast":`Las propias respuestas de la cámara dicen que ejecuta la compilación FF de 16 Hz: {why}.`,"write.ff.outcome.takes":`comprueba los datos antes de borrar una ranura, y estos datos pasan esa comprobación, así que puede escribir estos bytes tal cual, en una forma con la que su bootloader no puede arrancar: puede que la ranura no arranque (no se ha probado; la copia de seguridad guardada antes de la escritura la restaura)`,"write.ff.outcome.refuses":`comprueba los datos antes de borrar una ranura, y estos datos no pasan esa comprobación, así que se espera que rechace esta escritura antes de escribir nada (una cámara con esa compilación rechazó así una forma anterior de esta imagen)`,"write.ff.runsSlow":`La cámara ejecuta la compilación {version} de 8 Hz: {why}. Esa compilación {outcome}.`,"write.ff.buildUnknown":`Las propias respuestas de la cámara no dicen qué compilación {version} ejecuta: {why}. Si ejecuta la compilación FF de 16 Hz, acepta estos datos. Si ejecuta la compilación de 8 Hz, esa compilación {outcome}.`,"write.raw.asGiven":`Datos sin procesar: se envían exactamente como se dieron. Nada de lo que hay aquí comprueba que arranquen.`,"write.raw.ffStagedForm":`Estos datos son la forma de transferencia de 1.3.0.8 FF (la imagen XOR el bloque de claves 0, suma de palabras 0xFFFF). La cámara almacena la imagen con la clave B, así que la relectura se compara con esos bytes.`,"write.raw.noStaging":`Esta compilación no indica ninguna forma de transferencia para la ranura, así que no se pueden indicar las comprobaciones del bootloader.`,"write.raw.reencrypts":`El dispositivo decodifica estos datos y vuelve a cifrar lo que guarda, así que no se pueden predecir los bytes almacenados. La relectura se comprueba como la imagen que resulta al descifrarla, cuando eso se puede saber.`,"write.raw.bootloaderRejects":`El bootloader rechazaría estos datos: {failure}.`,"write.raw.stageKeyUnchecked":`La clave de transferencia de 2016 (bloque de claves 0) no está en los bytes sin procesar, así que aquí no se comprueba la suma de palabras descifrada de estos datos.`,"write.image.rekeyRisk":`{name:ins} ya contiene una imagen que el bootloader no puede aceptar. Esta escritura termina en el mismo estado.`,"write.ack.recovery":`Ranura de recuperación R: para escribir en ella tienes que aceptar el riesgo. Nada de lo que hay aquí comprueba que la cámara arranque después.`,"write.ack.risk":`{risk}: para escribir en ella tienes que aceptar el riesgo, y la cámara ejecuta lo que contenga después del próximo apagado y encendido.`,"write.ack.bootUnnamed":`no se pudo identificar la ranura de arranque, así que esta se trata como la de arranque`,"write.ack.recoveryFallback":`La ranura de recuperación R es la copia de último recurso a la que recurre el bootloader`,"boot.cfg0.modernBlank":`en blanco/0: preferir la ranura A, luego la B, luego la de recuperación`,"boot.cfg0.modernB":`preferir la ranura B, luego la A, luego la de recuperación`,"boot.cfg0.modernRecovery":`preferir la de recuperación, luego la A, luego la B`,"report.nextStart.unknown":`no se sabe: {why}`,"report.nextStart.runs":`{bank} — {why}`,"upgrade.whileRecovery":`La cámara está ejecutando su ranura de recuperación, y su propia actualización escribe {name:loc}, que no está ejecutando. {verdict} Esto es solo una advertencia: nada de lo que hay aquí impide una actualización.`,"upgrade.verdict.notRead":`No se pudo leer {name:acc} en esta comprobación, así que no se sabe qué contiene.`,"upgrade.verdict.blank":`{name:ins} está en blanco, así que la actualización escribe en una ranura vacía.`,"upgrade.verdict.bootableSame":`{name:ins} contiene la misma imagen arrancable que la ranura que se ejecuta, y la actualización la sustituye. {name:ins} deja de poder arrancar si la actualización se detiene a medias.`,"upgrade.verdict.bootable":`{name}: contiene una imagen arrancable, que la actualización sustituye. Si la actualización se detiene a medias, deja de poder arrancar.`,"upgrade.verdict.unknown":`En esta lectura no se sabe si {name:acc} es arrancable, así que la actualización puede sustituir una imagen con la que la cámara arrancaría.`,"upgrade.verdict.notBootable":`{name:ins} no aparece como arrancable en esta lectura, así que la actualización no sustituye ninguna imagen con la que la cámara arrancaría.`,"report.booted.name":`{bank}`,"report.booted.entered":`{bank} — la ranura en la que entró el bootloader en este arranque, según lo registra`,"report.lastStart.notRead":`no se leyó`,"report.lastStart.noBank":`la cámara indica {word}, que no nombra ninguna ranura`,"report.lastStart.entered":`la cámara indica que entró {bank:loc} (palabra de ranura activa {word})`,"running.noVersion":`sin versión`,"running.why.otherVersion":`la cámara indica {version}, y solo {only} tiene dos compilaciones`,"running.why.noVerdicts":`la cámara no respondió a los veredictos de las ranuras (selectores 6, 7 y 8 de GetFirmwareInfo)`,"running.why.notRead":`no se leyó una ranura de la que dependen los veredictos, así que no se pueden predecir las respuestas`,"running.answers":`la cámara responde {answers}`,"running.answers.each":`A {a}, B {b}, R {r}`,"running.why.plain":`{answers}, que es lo que responde la compilación 1.3.0.8 de 8 Hz para estas ranuras ({predicted})`,"running.why.ff":`{answers}, que es lo que responde la compilación 1.3.0.8 FF de 16 Hz para estas ranuras ({predicted})`,"running.why.both":`{answers}, y las dos compilaciones responden exactamente eso para estas ranuras, así que las ranuras no permiten distinguirlas`,"running.why.neither":`{answers}, que no coincide con ninguna compilación (8 Hz: {plain}; 16 Hz FF: {ff})`,"imageBuild.noVersion":`La cabecera de esta imagen no indica ninguna versión de firmware, así que no se puede saber si es la compilación que ejecuta la cámara ({camera}). Comprueba que es la imagen que quieres escribir.`,"imageBuild.otherVersion":`Esta imagen es el firmware {image}; la cámara ejecuta {camera}.`,"imageBuild.otherVersionTaken":`Esta imagen es el firmware {image}; la cámara ejecuta {camera}. En esta línea la cámara solo comprueba que una imagen esté bien formada (su cabecera y su suma de palabras), no su versión, así que acepta esta imagen, y cuando arranca desde esta ranura ejecuta {image}.`,"imageBuild.otherVersionUnchecked":`Esta imagen es el firmware {image}; la cámara ejecuta {camera}. No se ha comprobado si esta cámara acepta una compilación distinta, ni si la ejecuta.`,"imageBuild.otherBuild":`Esta imagen es la compilación {version} de 8 Hz; la cámara ejecuta la compilación {version} FF de 16 Hz. La compilación de 16 Hz compara los datos con su propia forma FF cuando se confirma la escritura y rechaza los que no la cumplen, antes de borrar la ranura (según su código fuente). No se ha probado en una cámara escribir en ella la compilación de 8 Hz.`,"imageBuild.runningUnknown":`Esta imagen es la compilación {version} de 8 Hz. La cámara ejecuta {version}, que existe como compilación de 8 Hz y como compilación FF de 16 Hz, y sus propias respuestas no dijeron cuál ejecuta, así que no se puede saber si esta es su compilación.`,"bootFail.tooShort":`los datos ocupan {size} B, demasiado poco para contener una cabecera en 0x200`,"bootFail.noMagic":`no hay número mágico de imagen en 0x200 (se encontró {found}, el bootloader necesita {needs})`,"bootFail.lengthOutside":`header.length {length} está fuera de los datos de {size} B`,"bootFail.lengthNotPayload":`header.length {length} no es la longitud de los datos, {size}`,"bootFail.overStage":`{size} B supera el máximo de transferencia de {max} B`,"bootFail.plainSum":`suma de palabras almacenada {sum}; el bootloader de 2014 necesita 0`,"bootFail.noFooter":`no hay pie en {offset}: los datos terminan en {end}`,"bootFail.footerNotCode":`el pie en {offset} no es «CODE»: el bootloader usa su cargador segmentado`,"bootFail.footerLength":`la longitud del pie no es igual a header.length {length}`,"bootFail.keyASum":`descifrada con la clave A de esta cámara, la suma de palabras es {sum}; el bootloader necesita {needs}`,"keyConfidence.family":`verificada por la suma de comprobación`,"keyConfidence.structural":`verificada solo por la tabla de vectores`,"keyConfidence.unverified":`sin verificar`,"keyCheck.family":`clave verificada por la suma de comprobación {sum}`,"keyCheck.other":`clave {phrase}; suma de comprobación {sum}`,"staging.phrase.keyACiphertext":`transferidos con las claves propias de la cámara`,"staging.phrase.slotKeystreamCiphertext":`transferidos con la clave propia de la imagen`,"staging.phrase.plain":`transferidos sin cifrar`,"staging.phrase.keyAKeystream":`transferidos como la app del fabricante transfiere la imagen FF (XOR clave A)`,"staging.phrase.verbatim":`enviados tal como se dieron`,"written.committed":`se confirmaron {size} B {name:loc}, en {address}, {staged}; estado de la confirmación {status}`,"written.noReadWindow":`esta compilación no indica ninguna ventana de lectura para la ranura, así que no se releyó nada`,"written.readBackFailed":`la relectura falló: {error}`,"written.readBack":`releídos {size} B, SHA-256 {sha256}`,"written.verifyOff":`la verificación está desactivada: la ranura no se releyó`,"readBack.reference.folded":`los bytes que el plan predijo para la ranura (la imagen tal como la almacena la compilación de 16 Hz, no los bytes enviados)`,"readBack.reference.asSent":`los bytes que el plan predijo para la ranura (los bytes tal como se enviaron)`,"readBack.sizeDiffers":`la relectura ocupa {size} B y el plan predijo {predictedSize} B: la ranura NO coincide con {reference}`,"readBack.matchesFolded":`la ranura contiene la imagen tal como la almacena la compilación de 16 Hz (no los bytes enviados), y el resto de la ranura está borrado`,"readBack.matches":`la ranura coincide con los bytes que predijo el plan (la cadena sin cifrar de 2014 programa exactamente lo que recibe)`,"readBack.differs":`la ranura NO coincide con {reference} (primera diferencia en {offset})`,"readBack.noHeader":`la relectura no contiene ninguna cabecera de imagen en {offset} (número mágico {magic}), así que la ranura NO se descifra como la imagen esperada`,"readBack.lengthDiffers":`la cabecera de la relectura indica {length} B y la imagen del plan ocupa {imageLength} B: la ranura NO se descifra como la imagen esperada`,"readBack.tooShort":`la relectura ocupa {size} B, demasiado poco para una imagen de {length} B: la ranura NO se descifra como la imagen esperada`,"readBack.recovered":`flujo de clave recuperado de la relectura ({check})`,"readBack.decrypts":`la ranura se descifra como la imagen esperada ({length} B) con el {recovered}`,"readBack.decryptDiffers":`la ranura NO se descifra como la imagen esperada: primera diferencia en el desplazamiento {offset} de la imagen, con el {recovered}`,"readBack.rawNotCompared":`bytes sin procesar: se informa de la relectura, pero no se compara (los bytes no se descifran como una imagen sin cifrar que se pueda predecir en esta forma, y el dispositivo vuelve a cifrar lo que guarda)`,"readBack.notCompared":`no fue posible ninguna comparación: el plan no predice ni los bytes almacenados ni la imagen sin cifrar`,"keyName.keyA":`clave A`,"keyName.keyA:acc":`la clave A`,"keyName.keyA:gen":`de la clave A`,"keyName.keyA:dat":`a la clave A`,"keyName.keyA:loc":`en la clave A`,"keyName.keyA:ins":`La clave A`,"keyName.keyB":`clave B`,"keyName.keyB:acc":`la clave B`,"keyName.keyB:gen":`de la clave B`,"keyName.keyB:dat":`a la clave B`,"keyName.keyB:loc":`en la clave B`,"keyName.keyB:ins":`La clave B`,"keyName.perDevice":`clave propia del dispositivo`,"keyName.perDevice:acc":`la clave propia del dispositivo`,"keyName.perDevice:gen":`de la clave propia del dispositivo`,"keyName.perDevice:dat":`a la clave propia del dispositivo`,"keyName.perDevice:loc":`en la clave propia del dispositivo`,"keyName.perDevice:ins":`La clave propia del dispositivo`,"keyName.thePerDevice":`la clave propia del dispositivo`,"keyName.thePerDevice:acc":`la clave propia del dispositivo`,"keyName.thePerDevice:gen":`de la clave propia del dispositivo`,"keyName.thePerDevice:dat":`a la clave propia del dispositivo`,"keyName.thePerDevice:loc":`en la clave propia del dispositivo`,"keyName.thePerDevice:ins":`La clave propia del dispositivo`,"keyName.applicationKeyA":`la clave A de la aplicación`,"keyName.applicationKeyA:acc":`la clave A de la aplicación`,"keyName.applicationKeyA:gen":`de la clave A de la aplicación`,"keyName.applicationKeyA:dat":`a la clave A de la aplicación`,"keyName.applicationKeyA:loc":`en la clave A de la aplicación`,"keyName.applicationKeyA:ins":`La clave A de la aplicación`,"keyName.applicationKeyB":`la clave B de la aplicación`,"keyName.applicationKeyB:acc":`la clave B de la aplicación`,"keyName.applicationKeyB:gen":`de la clave B de la aplicación`,"keyName.applicationKeyB:dat":`a la clave B de la aplicación`,"keyName.applicationKeyB:loc":`en la clave B de la aplicación`,"keyName.applicationKeyB:ins":`La clave B de la aplicación`,"keyName.block1":`bloque de claves 1`,"keyName.block1:acc":`el bloque de claves 1`,"keyName.block1:gen":`del bloque de claves 1`,"keyName.block1:dat":`al bloque de claves 1`,"keyName.block1:loc":`en el bloque de claves 1`,"keyName.block1:ins":`El bloque de claves 1`,"keyName.theDeviceKey":`la clave del dispositivo`,"keyName.theDeviceKey:acc":`la clave del dispositivo`,"keyName.theDeviceKey:gen":`de la clave del dispositivo`,"keyName.theDeviceKey:dat":`a la clave del dispositivo`,"keyName.theDeviceKey:loc":`en la clave del dispositivo`,"keyName.theDeviceKey:ins":`La clave del dispositivo`,"keyName.unknown":`clave desconocida`,"keyName.unknown:acc":`una clave desconocida`,"keyName.unknown:gen":`de una clave desconocida`,"keyName.unknown:dat":`a una clave desconocida`,"keyName.unknown:loc":`en una clave desconocida`,"keyName.unknown:ins":`Una clave desconocida`,"keys.evidence.plainChain":`la cadena sin cifrar de 2014: todas las ranuras se almacenan sin cifrar, así que no se deriva ninguna clave de envío; lo que se envía es la imagen tal cual`,"keys.evidence.ffVendor":`la compilación 1.3.0.8 FF (16 Hz): ninguna ranura que haya abierto esta lectura está almacenada sin cifrar, así que no consta que la cámara esté en la cadena sin cifrar de 2014; la imagen FF se escribe en la forma del fabricante, los bytes sin procesar se envían tal como se dieron, y no se escribe una imagen sin cifrar de 8 Hz`,"keys.evidence.ffUntested":`se ofrece escribir la imagen FF con su advertencia UNTESTED (sin probar): no hay en la colección ningún bootloader auténtico de esta compilación, así que no se ha medido si la ranura escrita arranca`,"keys.evidence.line2016":`la línea Compact PRO de 2016: lo que se envía es la imagen XOR el flujo de clave de su propio bloque de claves 0, que se encuentra en la imagen por su valor, así que no interviene ninguna clave de esta cámara`,"keys.evidence.checkKeyUnnamed":`la cámara descifra los datos enviados con esa clave y los vuelve a cifrar con la clave con la que su bootloader comprueba una ranura; esa clave no se identificó en esta lectura, y la escritura no la necesita: la ranura se relee como la imagen que resulta al descifrarla`,"keys.evidence.checkKeyUnnamedWhy":`la cámara descifra los datos enviados con esa clave y los vuelve a cifrar con la clave con la que su bootloader comprueba una ranura; esa clave no se identificó en esta lectura ({why}), y la escritura no la necesita: la ranura se relee como la imagen que resulta al descifrarla`,"keys.evidence.checkKeyNamed":`la cámara descifra los datos enviados con esa clave y los vuelve a cifrar con {key:acc} {hex}, la clave con la que su bootloader comprueba una ranura, así que cada ranura que escribe queda almacenada como el bootloader la acepta`,"keys.evidence.checkKeyInferred":`la cámara descifra los datos enviados con esa clave y los vuelve a cifrar con {key:acc} {hex}, la clave con la que su bootloader comprueba una ranura (deducida {bank:gen}, la ranura en la que la cámara indica que entró y en la que el bootloader entró sin hacer su comprobación), así que cada ranura que escribe queda almacenada como el bootloader la acepta`,"keys.evidence.checkKeyNamedFrom":`la cámara descifra los datos enviados con esa clave y los vuelve a cifrar con {key:acc} {hex}, la clave con la que su bootloader comprueba una ranura (identificada a partir {bank:gen}, la ranura en la que la cámara indica que entró), así que cada ranura que escribe queda almacenada como el bootloader la acepta`,"keys.refused.bootUnnamed":`no se pudo identificar la ranura de arranque, así que no se puede leer de ella la clave con la que se almacena la ranura`,"keys.refused.notDerived":`no se pudieron derivar las claves`,"keys.refused.notDecrypted":`{bank:acc}, con la que arrancó la cámara, no se descifra como una imagen, así que no se puede leer la clave con la que está almacenada`,"keys.refused.noBootKey":`{bank:acc}, con la que arrancó la cámara, no se descifra con ninguna clave que pruebe el bootloader (su clave A o su clave de almacenamiento), así que no se puede leer de ella la clave con la que está almacenada`,"keys.refused.keyNotInTable":`{bank:acc}, con la que arrancó la cámara, se descifra con {key:acc}, pero la tabla de claves de esta cámara no contiene esa clave, así que no se puede escribir con ella`,"keys.refused.noApplicationPair":`la aplicación en ejecución ({bank}, firmware {firmware}) no lleva ninguno de los pares de claves conocidos (el del bootloader y los pares de aplicación decodificados), cada mitad exactamente una vez, así que no se puede localizar su clave A en su imagen`,"keys.refused.noApplicationPairCounted":{one:`la aplicación en ejecución ({bank}, firmware {firmware}) no lleva ninguno de los pares de claves conocidos (el del bootloader y los pares de aplicación decodificados), cada mitad exactamente una vez, así que no se puede localizar su clave A en su imagen (la clave A del bootloader aparece {count} vez; su clave B, {keyB})`,many:`la aplicación en ejecución ({bank}, firmware {firmware}) no lleva ninguno de los pares de claves conocidos (el del bootloader y los pares de aplicación decodificados), cada mitad exactamente una vez, así que no se puede localizar su clave A en su imagen (la clave A del bootloader aparece {count} de veces; su clave B, {keyB})`,other:`la aplicación en ejecución ({bank}, firmware {firmware}) no lleva ninguno de los pares de claves conocidos (el del bootloader y los pares de aplicación decodificados), cada mitad exactamente una vez, así que no se puede localizar su clave A en su imagen (la clave A del bootloader aparece {count} veces; su clave B, {keyB})`},"keys.refused.uploadChecked":`la aplicación en ejecución ({bank}, firmware {firmware}) comprueba los datos enviados con sus propias claves antes de programarlos (el código fuente decodificado de esta compilación prueba los datos con su clave A y con su clave de almacenamiento, igual que su bootloader prueba una ranura), y la clave con la que almacenan las escrituras, {key:acc} ({hex}), no es ni su clave A ni su clave de almacenamiento, así que la cámara rechazaría los datos con 0x50000 antes de borrar nada`,"writeRefusal.acceptanceSum":`ninguna ranura se descifra con la suma de comprobación {sum} propia de {family}`,"writeRefusal.keyTable":`no se pudo confirmar la tabla de claves de esta cámara`,"writeRefusal.whitening":`la tabla de claves de esta cámara se resuelve con K={k}, pero {family} cifra con K={expected}`,"writeRefusal.otherFamily":`los indicios dicen que esta cámara es {detected}, no {family} ({reasons})`,"writeRefusal.camera":`en esta cámara no se puede escribir desde aquí: {reasons}`,"family.summary.modern":`Las compilaciones de Seek de 2018 en adelante (2.x, 4.x, 10.x, 42.x, 44.x): Compact 4.8/4.16, Compact Pro 4.9/4.18, Compact Pro FF, Compact XR, Mosaic 2.27/10.9, Nano 200 y Nano 300. Un volcado lee 63 de los 64 bloques de la flash sin desbloquear nada; en estas compilaciones ninguna lectura llega al bloque de {block}. El firmware se almacena cifrado. Las ranuras se escriben de una en una en la pestaña «Gestionar ranuras de firmware».`,"family.summary.early":`Las Compact de 2014 anteriores a 0.8.0.0: 0.3.0.1, 0.5.0.2, 0.5.1.0, 0.5.1.3, 0.6.0.4, 0.7.0.7 y 0.7.0.8. Su firmware no puede responder a la lectura que envía un volcado, así que «Volcar», «Volcar todos los selectores», la lectura completa de la pestaña «Información» y la pestaña «Gestionar ranuras de firmware» las rechazan después de leer la versión; en 0.3.0.1, el comando con el que empieza un volcado prepararía en cambio una actualización de firmware. La ejecución de preservación lee 0.7.0.7 y 0.7.0.8 mediante otro comando al que responden esas dos compilaciones. Un volcado obtenido de otra forma se descifra como siempre.`,"family.summary.compact2016":`Las compilaciones 1.0.3.x de la Compact PRO (1.0.3.0 y 1.0.3.2). Responden a las lecturas exactamente como las Compact de 2014, token de desbloqueo incluido, así que se distinguen por su versión y por cómo se almacenan sus ranuras: cifradas, mientras que las ranuras de 2014 están sin cifrar. Una cámara 1.0.3.x se lee con esta familia desde el principio. La ejecución de preservación lee toda la flash, y las ranuras se escriben de una en una en la pestaña «Gestionar ranuras de firmware».`,"family.summary.legacy":`Las Compact de 2014 de 0.8.0.0 a 1.3.0.8, entre ellas la compilación 1.3.0.8 FF de 16 Hz. Una cámara de serie deja leer menos de la mitad de su flash, parte de ella solo con un token de desbloqueo que envía la herramienta; la ejecución de preservación lee el resto mediante un parche temporal. Las ranuras se almacenan sin cifrar, salvo en la compilación FF. Una cámara Compact PRO 1.0.3.x se lee como compact-2016, y pasa a esta familia solo cuando una ranura está almacenada sin cifrar o se descifra con {sum}, como las de la compilación FF. Las ranuras se escriben en la pestaña «Gestionar ranuras de firmware» en las compilaciones con las que se midió la ejecución de preservación; cualquier otra compilación 0.x o 1.x solo se lee.`,"family.summary.generic":"Una cámara que no coincide con ninguna otra familia. `seek-fw dump` la lee con la lista de bloques de 4.x (la pestaña 4.x/Nano la rechaza), y un descifrado resuelve la clave a partir de la propia imagen, así que ninguno de los dos depende de la suposición. No se escribe ninguna ranura: la pestaña «Gestionar ranuras de firmware» la rechaza hasta que se identifique la cámara.","detect.source.header":`la cabecera de la imagen dice`,"detect.source.camera":`la cámara indica`,"detect.plainArmedNotInForce":`un BeginFirmwareUpgrade simple de 2 bytes abrió una ranura protegida, así que el canal de lectura autenticado no está en vigor`,"detect.modern.plainRefused":`se RECHAZÓ un BeginFirmwareUpgrade simple de 2 bytes sobre una ranura protegida, algo que no hace ninguna compilación de esta línea: su manejador no comprueba ningún token y acepta el canal simple en todas las ranuras`,"detect.modern.authArmed":`una ranura protegida se abrió con el selector autenticado de 18 bytes; ahí no se probó el simple, así que eso no saca a esta cámara de esta línea`,"detect.modern.legacyVersion":`{said} firmware {version}, que pertenece a la línea antigua 0.x / 1.x (otra línea de numeración, no una 4.x más antigua; y una de esas compilaciones también da la suma {sum})`,"detect.modern.noSum":`ninguna ranura se descifra con la suma de comprobación {sum} que exige el bootloader de esta familia`,"detect.modern.sum":`una ranura se descifra con la suma de comprobación {sum}`,"detect.modern.version":`el firmware {version} pertenece a la línea posterior a 2018 que cubre este mapa de selectores (2.x / 4.x / 10.x / 42.x / 44.x: Compact, Compact Pro, Compact XR, Mosaic, Nano)`,"detect.modern.plainWorks":`un BeginFirmwareUpgrade simple de 2 bytes abrió una ranura protegida, así que no es el firmware antiguo bloqueado`,"detect.modern.none":`ningún indicio sitúa esta cámara en la línea posterior a 2018`,"detect.early.noVersion":`no se indicó ninguna versión de firmware ni se encontró ninguna en la cabecera de una imagen`,"detect.early.readable":`el firmware {version} es {first} o posterior, así que su tabla RPC tiene un lector para GetFeaturedFirmwareData y se aplica la vía de lectura normal`,"detect.early.older":`{said} firmware {version}, anterior a {first}, la primera compilación cuya tabla de métodos RPC tiene un manejador de lectura (lector) para GetFeaturedFirmwareData`,"detect.early.noWindow":`y no se pudo leer ninguna ventana, que es lo que eso predice`,"detect.generic.fallback":`alternativa: ninguna familia de firmware coincidió con seguridad, así que las lecturas siguen disponibles y las escrituras no`,"detect.compact2016.early":`el firmware {version} es anterior a 0.8.0.0 y no tiene manejador de lectura para GetFeaturedFirmwareData: eso es early-compact, no esta familia`,"detect.compact2016.modernSum":`una ranura se descifra con la suma de comprobación {sum}, que no es el objetivo de esta generación`,"detect.compact2016.plainArmed":`un BeginFirmwareUpgrade simple de 2 bytes abrió una ranura protegida, así que esta cámara no está en la línea bloqueada que esta familia comparte con legacy-auth`,"detect.compact2016.notLine":`el firmware {version} no pertenece a la línea 0.x / 1.x`,"detect.compact2016.storedPlain":`una ranura está almacenada sin cifrar (la resolución del flujo de clave devuelve el estado identidad, así que sus palabras almacenadas SON la imagen), y eso es la cadena sin cifrar de 2014; las ranuras de esta generación van en xorshift128 con una clave real`,"detect.compact2016.keyedZero":`una ranura almacenada con un flujo de clave xorshift128 real se descifra con la suma de comprobación {sum}, que es el cifrado de esta generación`,"detect.compact2016.zeroSum":`una ranura se descifra con la suma de comprobación {sum}, que es el objetivo de esta generación`,"detect.compact2016.refused":`y una ranura protegida rechazó la apertura simple de 2 bytes, que es el manejador bloqueado`,"detect.compact2016.proLine":`{said} firmware {version}, la línea 1.0.3.x de la Compact PRO de 2016`,"detect.compact2016.compactLine":`{said} firmware {version}, una compilación de la Compact, no la línea 1.0.3.x de la Compact PRO`,"detect.compact2016.lockedLine":`{said} firmware {version}, de la línea 0.x / 1.x que esta generación comparte con el firmware antiguo bloqueado`,"detect.compact2016.bootloader2016":`el bootloader indica {version}, un bootloader de la generación de 2016 (1.2.0.0 se midió con la Compact PRO 1.0.3.0; el de la Compact de 2014 es 0.9.0.0)`,"detect.compact2016.bootloader2014":`el bootloader indica {version}, la numeración de la generación de 2014, no la de esta generación`,"detect.compact2016.none":`no se observó ninguna ranura que se descifrara con una suma de comprobación cero con una clave real`,"detect.legacy.proLine":`pero el firmware {version} es de la línea 1.0.3.x de la Compact PRO de 2016, cuyas ranuras usan el cifrado de compact-2016: la comprobación de esta familia fallaría en todas ellas`,"detect.legacy.early":`el firmware {version} es anterior a 0.8.0.0: su tabla RPC no tiene manejador de lectura para GetFeaturedFirmwareData (ninguno antes de 0.7.0.7, y solo uno de escritura en 0.7.0.7 y 0.7.0.8): eso es early-compact, no esta familia`,"detect.legacy.keyedZero":`una ranura almacenada con un flujo de clave xorshift128 real se descifra con {zero}: el cifrado de la Compact PRO de 2016 (compact-2016). Esta línea almacena sus ranuras sin cifrar con una suma de palabras 0 (la cadena de 2014) o con clave hasta {sum} (Compact 1.3.0.8), y su comprobación falla con una ranura así`,"detect.legacy.plainChain":`una ranura está almacenada como firmware sin cifrar cuyas palabras suman 0, tal como la arranca el bootloader de 2014 de esta línea`,"detect.legacy.refused":`la cámara se negó a abrir una ranura bloqueada para una actualización cuando se le pidió sin el desbloqueo, algo que solo hace esta generación de firmware`,"detect.legacy.unlocked":`y abrió la misma ranura cuando se le pidió con el desbloqueo, así que el desbloqueo que envía esta familia es el que comprueba esta cámara`,"detect.legacy.notLine":`{said} firmware {version}, que no pertenece a la línea antigua 0.x / 1.x`,"detect.legacy.authOnly":`abrió una ranura bloqueada para una actualización cuando se le pidió con el desbloqueo, como hace esta generación de firmware; no se probó a pedirlo sin el desbloqueo, así que esto solo no demuestra la generación`,"detect.legacy.version":`el firmware {version} pertenece a la línea antigua 0.x / 1.x, que es otra línea de numeración distinta de las versiones de aplicación posteriores a 2018, no una 4.x más antigua`,"detect.legacy.none":`nada de lo observado apunta al canal de lectura autenticado`,"fps.table.withheld":`retenido tras una prueba en una cámara: allí el parche no subió la frecuencia de publicación, y el obturador se disparó en cada fotograma después de la escritura`,"fps.table.predates":`el firmware {version} es anterior a 0.8.0.0: su tabla RPC no tiene manejador de lectura para GetFeaturedFirmwareData, el comando que envía una lectura de ranura, así que la pestaña de ranuras no lee ni escribe ninguna ranura de esa compilación, y no se ofrece el parche`,"fps.table.stageTwoFf":`stage two: la compilación FF de 16 Hz se transfiere como la transfiere la app del fabricante (la imagen XOR la clave A, almacenada con la clave B), no como bytes sin cifrar, así que su comprobación de transferencia no está hecha y el parche aún no se ofrece`,"fps.table.stageTwo":`stage two: esta entrada no está en el conjunto de stage two, así que su comprobación de transferencia no está hecha y el parche aún no se ofrece`,"fps.table.notOffered":`no se ofrece`,"fps.table.notImage":`esto no es una imagen de firmware, así que no se le aplica ningún parche de velocidad de fotogramas`,"fps.table.otherBuild":`la imagen es la compilación {image}, pero la cámara indica {camera}; el parche se rechaza en lugar de aplicarse a una compilación con la que no coincide`,"fps.table.otherBuildNoVersion":`la imagen es la compilación {image}, pero la cámara no indica ninguna versión; el parche se rechaza en lugar de aplicarse a una compilación con la que no coincide`,"fps.table.patched":`el parche de velocidad de fotogramas ya está aplicado: esta imagen funciona a {hz} Hz`,"fps.table.earlierPatch":`esta imagen contiene un parche anterior de velocidad de fotogramas de {hz} Hz sin la corrección de USB, y nunca se aplica un parche a una imagen ya parcheada: restaura la imagen de serie y luego aplícale el parche`,"fps.table.atRate":`esta compilación ya funciona a {hz} Hz sin parche`,"fps.table.not4821":`esta imagen indica la compilación 4.8.2.1 de la Compact (o la de la Compact XR 4.8.2.1, la misma compilación), pero no es la imagen de serie para la que se escribió el parche de velocidad de fotogramas (f96ac57eda75: sus páginas de comandos de 68 bytes, página estable 13), así que no se crea ningún parche de velocidad de fotogramas para ella`,"fps.table.notInTable":`esta imagen no está en la tabla de parches de velocidad de fotogramas, así que no se crea ningún parche de velocidad de fotogramas para esta compilación. La tabla incluye las compilaciones de la Compact de 0.7.0.8 a 1.3.0.8 (8 Hz; el código de ranuras rechaza 0.7.0.8), 1.3.0.8 (16 Hz FF), 4.8.1.7, 4.8.1.9, 4.8.2.1 y 4.16.1.7 FF, y las compilaciones 1.0.3.x y 4.9.x de la Compact PRO; ninguna otra compilación tiene entrada`,"fps.plan.noBank":`el plan de esta compilación no tiene {bank:acc}`,"fps.plan.noPlain":`{bank:acc} no puede recibir una imagen descifrada en esta compilación: {reason}`,"fps.plan.empty":`{bank:acc} no tiene ninguna imagen descifrada a la que aplicar el parche (está vacía)`,"fps.plan.noImage":`{bank:acc} no tiene ninguna imagen descifrada a la que aplicar el parche (no se leyó o ninguna clave la abre)`,"fpsEvery.stopped.readBack":`{name:ins} se escribió, pero su relectura no difiere de la ranura guardada solo según lo previsto, así que no se escribieron las ranuras siguientes`,"fpsEvery.stopped.error":`{name}: {error}`,"notes.unverified":`Solo lectura. La disposición de las ranuras es la tabla decodificada de la línea bloqueada, pero no se ha medido ninguna forma de transferencia para esta compilación, así que no se planifica ninguna escritura.`,"identity.versionUnknown":`la cámara no indicó su versión de firmware ({note}); un número de comando no significa lo mismo en todos los firmware de Seek (en la Compact 0.3.0.1, el wire id 0x52, el que abre una ventana de lectura, es EnterBootloaderMode), así que hasta conocer la versión no se envía nada salvo GetErrorCode, GetOperationMode y GetFirmwareInfo, las lecturas a las que todas las compilaciones responden igual`,"identity.note.startup":`GetFirmwareInfo no respondió ({error}) en ninguna de {reads} lecturas separadas {spacing} ms, un margen de arranque de {window} ms; una cámara que aún está arrancando responde dentro de ese margen`,"identity.note.neverTwice":`GetFirmwareInfo nunca respondió dos veces seguidas en {reads} lecturas`,"identity.note.noAnswer":`GetFirmwareInfo no respondió ({error})`,"identity.note.noAnswerSome":`GetFirmwareInfo no respondió ({error}); respondieron {answered} de {reads} lecturas, nunca dos seguidas, así que ninguna se puede distinguir de un registro que dejó seleccionado un comando anterior`,"identity.note.tooShort":{one:`GetFirmwareInfo respondió con {count} byte, demasiado pocos para una versión`,many:`GetFirmwareInfo respondió con {count} de bytes, demasiado pocos para una versión`,other:`GetFirmwareInfo respondió con {count} bytes, demasiado pocos para una versión`},"identity.note.tooShortContext":{one:`GetFirmwareInfo respondió con {count} byte, demasiado pocos para una versión; {context}`,many:`GetFirmwareInfo respondió con {count} de bytes, demasiado pocos para una versión; {context}`,other:`GetFirmwareInfo respondió con {count} bytes, demasiado pocos para una versión; {context}`},"identity.note.otherRecord":`la primera lectura respondió con otro registro ({version}), en el que un comando anterior había dejado el selector de información del firmware; esa lectura lo restableció`,"identity.note.afterStartup":{one:`respondió después de rechazar {count} lectura mientras arrancaba`,many:`respondió después de rechazar {count} de lecturas mientras arrancaba`,other:`respondió después de rechazar {count} lecturas mientras arrancaba`},"identity.predates":`el firmware {version} es anterior al protocolo de volcado: su tabla de métodos RPC no tiene manejador de lectura para GetFeaturedFirmwareData (en 0.7.0.7 y 0.7.0.8 solo está registrado como escritura, y antes de eso el wire id 0x4F es UploadFirmwareRowSize), así que no se puede leer ninguna ventana con él; en 0.3.0.1 el wire id 0x52 es EnterBootloaderMode en lugar de BeginFirmwareUpgrade. La ejecución de preservación lee 0.7.0.7 y 0.7.0.8 mediante el wire id 0x58 (GetFeaturedData)`,"identity.refusing":`se rechaza {operation}: {reason}`,"identity.refusingNoVersion":`se rechaza {operation}: {reason}. No se abrió nada. Desconecta la cámara, vuelve a conectarla, deja que termine de arrancar y vuelve a intentarlo.`,"identity.operation.dump":`el volcado`,"identity.operation.dumpAll":`el volcado de todos los selectores`,"identity.operation.readInfo":`la lectura de la información del dispositivo`,"preserve.banks.beforeBackup":`las ranuras se eligen después de la copia de seguridad, que las lee: haz primero la copia de seguridad`,"preserve.banks.afterCommit":`las ranuras no pueden cambiar una vez hecha o intentada la escritura; esta ejecución escribe en: {banks}. La restauración vuelve a poner exactamente esas`,"preserve.banks.none":`ninguna ranura`,"status.written":`Escrito.`,"status.read":`Leído. {count}/{of} ranuras legibles.`,"status.readRefused":`Leído, pero desde aquí no se puede escribir en ninguna ranura de esta cámara: consulta el registro.`,"compare.field.version":`Versión de firmware`,"compare.field.imageId":`Id. de imagen`,"compare.field.initialSp":`SP inicial`,"compare.field.resetVector":`Vector de reinicio`,"compare.field.size":`Tamaño`,"compare.field.shaExpected":`SHA-256 de la imagen sin cifrar esperada`,"compare.field.sha":`SHA-256 de la imagen`,"compare.field.shaNotStored":`SHA-256 de la imagen sin cifrar esperada (bytes almacenados no predichos)`,"compare.field.key":`Clave`,"compare.noImage":`(sin imagen)`,"compare.notImage":`(no es una imagen)`,"compare.notPredicted":`(no predicho: el dispositivo decide qué almacena)`,"compare.plaintext":`ninguna (sin cifrar)`,"boot.verdict.unsettled":`no se pudo leer igual dos veces`,"preserve.boot.inferred":`{why} (la clave con la que el bootloader comprueba una ranura se deduce {bank:gen}, en la que entró sin su comprobación) [inferred]`,"preserve.lastStart.entered":`{bank}, según lo registra la cámara (palabra de ranura activa {word})`,"preserve.lastStart.notRead":`no se sabe: no se pudo leer la palabra de ranura activa`,"preserve.lastStart.noBank":`no se sabe: la palabra de ranura activa es {word}, que no nombra ninguna ranura`,"preserve.nextStart.known":`{bank} — {why}`,"preserve.nextStart.unknown":`no se sabe: {why}`,"preserve.bank.notWritten":`no se escribe: {reason}`,"preserve.bank.anImage":`una imagen`,"preserve.bank.writable":`{build}: se puede escribir`,"preserve.bank.writablePatch":`{build}: se puede escribir; el parche cambia {count} bytes`,"preserve.bank.writableEdit":`{build}: se puede escribir; lleva {edit}`,"preserve.bank.writablePatchEdit":`{build}: se puede escribir; el parche cambia {count} bytes; lleva {edit}`,"preserve.choice.notRead":`la copia de seguridad aún no ha leído las ranuras, así que no se puede elegir ninguna`,"preserve.choice.every":`todas las ranuras que contienen una imagen: {banks}`,"preserve.choice.everyBlocked":`no se puede escribir en todas las ranuras que contienen una imagen: en {bank:acc} no se puede ({reason})`,"preserve.choice.noImage":`ninguna ranura contiene una imagen que la ejecución pueda escribir`,"preserve.choice.nextStart":`{bank}, la ranura del próximo arranque: {why}`,"preserve.choice.nextStartRefused":`el próximo arranque entra {bank:loc} ({why}), y la ejecución no puede escribir en ella: {reason}`,"preserve.choice.everyUnknownStart":`todas las ranuras que contienen una imagen ({banks}): no se sabe en qué ranura entra el próximo arranque ({why})`,"preserve.choice.unknownStartRefused":`no se sabe en qué ranura entra el próximo arranque ({why}), y {reason}; elige una ranura por su nombre`,"preserve.choice.bank":`{bank}`,"preserve.choice.bankRefused":`no se puede escribir en {bank:acc}: {reason}`,"preserve.choice.byName":`{banks}, la ranura elegida por su nombre`,"preserve.choice.warnNotPatched":`El próximo arranque entra {bank:loc} ({why}), y esta elección no le aplica el parche: tras el reinicio, la cámara ejecuta la imagen propia de esa ranura, así que la lectura completa se detiene antes de leer nada. La restauración vuelve a poner igualmente todas las ranuras escritas.`,"preserve.choice.warnUnknownStart":`No se sabe en qué ranura entra el próximo arranque ({why}). Si entra en una ranura a la que esta elección no aplica el parche, la lectura completa se detiene antes de leer nada.`,"preserve.build.notKnown":`aún no se sabe`,"preserve.build.firmware":`firmware {version}`,"preserve.stagedForm.plain":`tal como lo almacena la cámara (esta cámara guarda su firmware sin cifrar)`,"preserve.stagedForm.oneKey":`en la forma en que lo almacena la cámara (cifrado con la clave de la cámara)`,"preserve.stagedForm.twoKeys":`en la forma en que lo almacena la cámara (cifrado con las dos claves de la cámara)`,"preserve.restoreForm.verbatim":`cada ranura escrita recupera exactamente los bytes que la copia de seguridad leyó de ella`,"preserve.restoreForm.factoryStaged":`cada ranura escrita recupera su firmware original, escrito en la forma en que lo almacena la cámara, así que la ranura queda byte a byte como la leyó la copia de seguridad`,"preserve.restoreForm.none":`no es posible en esta compilación: ninguna forma del firmware original pasa la propia comprobación de la cámara y a la vez se almacena como los bytes originales, así que la ejecución termina con la imagen completa y con el parche aún puesto`,"preserve.drain.notPossible":`no es posible en esta compilación: el firmware con el parche no puede leer toda la flash, así que la ejecución no tiene ninguna imagen completa que dar`,"preserve.drain.rotated":`la cámara la entrega rotada, y la ejecución la vuelve a poner en orden`,"preserve.drain.hazard":`el parche evita una lectura que en esta compilación bloquea la cámara`,"preserve.drain.whole":`toda la flash de 4 MB en una lectura, de {size} en {size} bytes`,"preserve.drain.wholeNotes":`toda la flash de 4 MB en una lectura, de {size} en {size} bytes; {notes}`,"preserve.site.wholeFlash":`permite que el comando de lectura de la cámara llegue a toda la flash de 4 MB, no solo a los primeros 64 KB`,"preserve.site.countPast":`permite que la posición de lectura pase de 64 KB, para que una lectura no vuelva al principio`,"preserve.site.keepPosition":`conserva la posición de lectura completa cuando avanza después de cada lectura`,"preserve.site.savePosition":`guarda completa la posición de lectura ya avanzada`,"preserve.site.clearPosition":`borra la posición de lectura completa cada vez que empieza una lectura, para que la cámara se pueda seguir leyendo después de la lectura completa`,"preserve.site.modeTwoGuard":`deja que la lectura completa empiece como cualquier otra lectura (el firmware de serie la rechaza)`,"preserve.site.modeTwoIndirection":`hace que la lectura completa apunte al principio de la flash (el firmware de serie la hace apuntar a un valor que bloquea la cámara)`,"preserve.site.armTail":`quita una llamada que congela la cámara cuando empieza una lectura en esta compilación`,"preserve.site.other":`cambia una instrucción que necesita la lectura completa`,"preserve.step.backup":`Copia de seguridad`,"preserve.step.patch":`Parche`,"preserve.step.commit":`Escritura`,"preserve.step.drain":`Lectura completa`,"preserve.step.restore":`Restauración`,"preserve.step.verify":`Comprobación`,"preserve.stepId.patch":`el paso «Parche»`,"preserve.stepId.commit":`el paso «Escritura»`,"preserve.stepId.drain":`el paso «Lectura completa»`,"preserve.stepId.restore":`el paso «Restauración»`,"preserve.stepId.verify":`el paso «Comprobación»`,"preserve.result.stoppedPlanned":`{label}: detenido según lo previsto. La cámara arrancó desde {bank:acc}, a la que esta ejecución no aplicó el parche, así que no se leyó nada.`,"preserve.result.noReason":`no se registró ningún motivo`,"preserve.result.stopped":`{label}: detenido — {error}`,"preserve.result.writable.none":`ninguna ranura contiene firmware al que la ejecución pueda aplicar el parche`,"preserve.result.writable.one":`{banks:acc} contiene firmware al que la ejecución puede aplicar el parche`,"preserve.result.writable.many":`{banks:acc} contienen firmware al que la ejecución puede aplicar el parche`,"preserve.result.backup":`{label}: se guardaron todos los bloques que alcanza una lectura normal; {writable}.`,"preserve.result.nextUnknown":`una ranura desconocida`,"preserve.result.backupNext":`{label}: se guardaron todos los bloques que alcanza una lectura normal; {writable}; ranura del próximo arranque: {next}.`,"preserve.result.patch":`{label}: creado para {banks:acc}.`,"preserve.result.patchNone":`{label}: no se creó ningún parche: ninguna ranura contiene firmware al que la ejecución pueda aplicarlo.`,"preserve.result.patchCount":`{label}: creado para {banks:acc}; cambian {count} bytes en cada una.`,"preserve.result.commitOne":`{label}: se escribió el parche {banks:loc}, y la cámara lo aceptó.`,"preserve.result.commitMany":`{label}: se escribió el parche {banks:loc}, y la cámara aceptó cada escritura.`,"preserve.result.drainNotRead":`{label}: no se leyó.`,"preserve.result.drain":`{label}: se leyó toda la flash de 4 MB; la imagen completa tiene sha256 {sha256}.`,"preserve.result.drainThrough":`{label}: se leyó toda la flash de 4 MB a través {bank:gen}; la imagen completa tiene sha256 {sha256}.`,"preserve.result.restore":`{label}: se volvió a escribir el contenido original {banks:gen}.`,"preserve.result.restoreForm":`{label}: se volvió a escribir el contenido original {banks:gen}, {form}.`,"preserve.result.verifyDone":`{label}: hecho.`,"preserve.result.verifyIdentical":`{label}: se volvieron a leer {blocks} bloques y difieren 0 bytes; la flash de la cámara es idéntica byte a byte a la copia de seguridad.`,"preserve.result.verifyDiffers":`{label}: se volvieron a leer {blocks} bloques y difieren {bytes} bytes.`,"preserve.result.verifyDiffersUnread":{one:`{label}: se volvieron a leer {blocks} bloques, difieren {bytes} bytes y no se pudo leer {count} bloque.`,many:`{label}: se volvieron a leer {blocks} bloques, difieren {bytes} bytes y no se pudieron leer {count} de bloques.`,other:`{label}: se volvieron a leer {blocks} bloques, difieren {bytes} bytes y no se pudieron leer {count} bloques.`},"preserve.unpatchedStart.stop":`Detenido antes de la lectura completa: la cámara arrancó desde una ranura a la que esta ejecución no aplicó el parche, así que no se leyó nada.`,"preserve.unpatchedStart.next":`Siguiente paso: la restauración vuelve a poner todas las ranuras escritas. La lectura completa no se vuelve a intentar: la cámara arrancaría desde la misma ranura.`,"preserve.done.title":`Hecho: tu firmware está preservado`,"preserve.done.detail":`La imagen completa es toda la flash original de la cámara, y la propia cámara ha vuelto a estar exactamente como estaba.`,"preserve.done.titleNoImage":`Hecho: la cámara ha vuelto a estar como estaba; no hay imagen completa`,"preserve.done.detailNoImage":`La lectura completa no se ejecutó, así que esta ejecución no tiene ninguna imagen completa de la flash. Se volvieron a poner todas las ranuras escritas, y una lectura nueva de los bloques que alcanza un volcado normal coincide con la copia de seguridad. Para tener la imagen completa, empieza una ejecución nueva con una elección que incluya la ranura del próximo arranque.`,"preserve.done.detailNoImageCount":`La lectura completa no se ejecutó, así que esta ejecución no tiene ninguna imagen completa de la flash. Se volvieron a poner todas las ranuras escritas, y una lectura nueva de los {blocks} bloques que alcanza un volcado normal coincide con la copia de seguridad. Para tener la imagen completa, empieza una ejecución nueva con una elección que incluya la ranura del próximo arranque.`,"preserve.fail.spentReader":"el lector de ventanas de la cámara tiene un límite por arranque y estas lecturas vinieron de un lector agotado: apaga la cámara y vuelve a encenderla (desconéctala y vuelve a conectarla, o usa su interruptor) y vuelve a ejecutar `preserve --resume <run-directory>`. Firma: {signature}","preserve.fail.spentReaderDerive":"el lector de ventanas de la cámara tiene un límite por arranque y estas lecturas vinieron de un lector agotado: apaga la cámara y vuelve a encenderla (desconéctala y vuelve a conectarla, o usa su interruptor) y vuelve a ejecutar `preserve --resume <run-directory>`. Firma: {signature}. No se puede derivar ningún texto sin cifrar de fábrica de estos bytes. Se probaron todas las formas de leerlo:\n  - {reasons}","preserve.fail.notInBackup":`la copia de seguridad no contiene {bank:acc} ({address}): las ventanas de serie no pueden entregarla`,"preserve.fail.readsDisagree":`las dos lecturas {bank:gen} no coinciden (sha256 {sha256} frente a {other}): no se debe escribir en una cámara que no puede entregar dos veces seguidas igual la ranura que ejecuta; la captura es la fuente de la restauración y el punto de partida del parche`,"preserve.fail.notFactory":`{bank:ins} no contiene la imagen de fábrica tal como la almacena el cifrado de esta compilación (el principio esperado de la imagen no coincide con la captura): se rechaza antes de registrar nada, y mucho menos de escribir`,"preserve.fail.ffSum":`el firmware con el parche, en la forma en que lo almacena la cámara, no pasa la propia comprobación de esta compilación (su suma debe ser {sum}): se rechaza enviar una ranura que la cámara rechazaría después de borrarla`,"preserve.fail.headChanged":`el principio {bank:gen} ha cambiado desde la copia de seguridad (no contiene ni la captura original ni los bytes con el parche): se rechaza escribir sobre una ranura en un estado desconocido; no se escribió nada. Principio en hexadecimal: actual {live} frente a captura {capture}`,"preserve.fail.landedOne":`{banks:ins} ya contiene los bytes con el parche: la escritura se completó en un intento anterior y no debe repetirse. Reanuda en el paso de lectura completa (drain, --resume), que arranca la imagen con el parche y continúa desde ahí.`,"preserve.fail.landed":`Estas ranuras ya contienen los bytes con el parche: {banks}. La escritura se completó en un intento anterior y no debe repetirse. Reanuda en el paso de lectura completa (drain, --resume), que arranca la imagen con el parche y continúa desde ahí.`,"preserve.fail.drainRebootRefused":`el equipo RECHAZÓ el comando de reinicio de la lectura completa antes de que saliera (un SecurityError: una política del navegador o una protección de prueba), así que la cámara sigue ejecutando la imagen con la que arrancó, no el parche escrito. La lectura completa solo lee a través de la ventana ampliada de la imagen con el parche, así que se detiene antes de abrir nada; no se leyó nada. Vuelve a ejecutar la lectura completa donde el equipo deje pasar el comando de reinicio.`,"preserve.fail.shiftedRebootRefused":`la lectura completa volvió desplazada una página, y el equipo RECHAZÓ el reinicio que daría otro arranque antes de que saliera (un SecurityError: una política del navegador o una protección de prueba); otro intento leería el mismo arranque desplazado. No se guardó nada; vuelve a ejecutar la lectura completa donde el reinicio pueda salir.`,"preserve.fail.verify":{one:`la comprobación leyó {count} byte distinto en {read}/{total} ventanas: el chip no se relee idéntico byte a byte a la copia de seguridad`,many:`la comprobación leyó {count} de bytes distintos en {read}/{total} ventanas: el chip no se relee idéntico byte a byte a la copia de seguridad`,other:`la comprobación leyó {count} bytes distintos en {read}/{total} ventanas: el chip no se relee idéntico byte a byte a la copia de seguridad`},"preserve.fail.verifyIn":{one:`la comprobación leyó {count} byte distinto en {read}/{total} ventanas (en {places}): el chip no se relee idéntico byte a byte a la copia de seguridad`,many:`la comprobación leyó {count} de bytes distintos en {read}/{total} ventanas (en {places}): el chip no se relee idéntico byte a byte a la copia de seguridad`,other:`la comprobación leyó {count} bytes distintos en {read}/{total} ventanas (en {places}): el chip no se relee idéntico byte a byte a la copia de seguridad`},"preserve.fail.verifyShort":{one:`la comprobación leyó {count} byte distinto en {read}/{total} ventanas (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`,many:`la comprobación leyó {count} de bytes distintos en {read}/{total} ventanas (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`,other:`la comprobación leyó {count} bytes distintos en {read}/{total} ventanas (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`},"preserve.fail.verifyInShort":{one:`la comprobación leyó {count} byte distinto en {read}/{total} ventanas (en {places}) (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`,many:`la comprobación leyó {count} de bytes distintos en {read}/{total} ventanas (en {places}) (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`,other:`la comprobación leyó {count} bytes distintos en {read}/{total} ventanas (en {places}) (ventanas cortas: {short}): el chip no se relee idéntico byte a byte a la copia de seguridad`},"preserve.fail.verifyPlace":`{what} {address}`,"preserve.fail.bootConfigBlock":`el bloque de configuración de arranque`,"preserve.fail.dataBlock":`un bloque de datos`,"preserve.refused.secondRead":`su segunda lectura falló ({error})`,"preserve.refused.readsDisagree":`sus dos lecturas no coinciden (sha256 {sha256} frente a {other})`,"preserve.refused.erased":`está borrada`,"preserve.refused.watchdogMark":`su palabra de cabecera en +0x200 contiene {word}, la marca que el bootloader escribe sobre una ranura tras un reinicio del watchdog al principio de un arranque; el bootloader ya no acepta esta ranura, y la ejecución no tiene ahí ninguna imagen a la que aplicar el parche`,"preserve.refused.noHeader":`no contiene ninguna cabecera de imagen en +0x200`,"preserve.refused.otherBuild":`contiene {image} ({id}), no la compilación que ejecuta la cámara ({camera})`,"preserve.refused.otherKey":`la comprobación del bootloader la rechaza: está almacenada con una clave distinta de aquella con la que el bootloader de esta cámara comprueba las ranuras, y una escritura a través de la cámara la almacenaría con esa clave, así que la restauración no podría volver a poner sus bytes exactos`,"preserve.error.otherVersion":`la cámara indica el firmware {camera} y se esperaba {version}: el parche se deriva de los bytes de una compilación y no debe enviarse a otra`,"preserve.refused.outsideLine":`el firmware {version} no es una compilación 0.x ni 1.x, y esta ejecución solo cubre las compilaciones de 2014 y 2016. No se leyó nada más que la versión. Lee esta cámara con «Volcar y descifrar 4.x/Nano»: lee la flash sin parche, todos los bloques salvo el de 0x14060000, al que ninguna ventana de lectura llega en esas compilaciones.`,"preserve.refused.preWidening":`el firmware {version} es anterior a la vía de ampliación, y la ejecución se niega antes que escribir sobre una ranura que no puede releer. En esta generación la cámara rechaza todas las formas de iniciar la lectura que necesita esa vía (medido en 0.3.0.1), su comando de lectura no llega al principio de la flash, y el tamaño que cambiaría el parche se almacena de otra forma. Tampoco tiene ninguna lectura que pueda usar un volcado normal. No se leyó nada más que la versión.`,"preserve.image.unknown":`contiene una imagen desconocida (ni el firmware {version} de serie ni un cambio en él que Preserve conozca), así que Preserve no le aplica el parche ni la vuelve a poner`,"preserve.image.frameRate":`contiene una compilación conocida con cambio de velocidad de fotogramas: el firmware {version} de serie con el parche de velocidad de fotogramas de {hz} Hz. Preserve solo aplica su parche al firmware de serie, nunca a una imagen ya parcheada, así que no se lo aplica a esta ranura ni la vuelve a poner`,"preserve.image.frameRateEarlier":`contiene una compilación conocida con cambio de velocidad de fotogramas: el firmware {version} de serie con un parche anterior de velocidad de fotogramas de {hz} Hz (hecho antes de que se le añadiera la corrección de USB). Preserve solo aplica su parche al firmware de serie, nunca a una imagen ya parcheada, así que no se lo aplica a esta ranura ni la vuelve a poner`,"preserve.image.unknownWords":`esta ranura {what}. Para incluirla, vuelve a escribir antes en ella la imagen de serie (por ejemplo, desde una copia de seguridad completa de la flash hecha antes del cambio) y luego empieza una ejecución nueva`,"preserve.image.frameRateWords":`esta ranura {what}. Para incluirla, vuelve a escribir antes en ella la imagen de serie (por ejemplo, desde una copia de seguridad completa de la flash hecha antes del parche de velocidad de fotogramas) y luego empieza una ejecución nueva; después se puede volver a aplicar el parche de velocidad de fotogramas a la imagen de serie`,"preserve.image.unknownRefusal":`{name}: {what}. La ejecución toma de esta ranura el firmware al que aplica el parche, así que se detiene aquí, antes de escribir nada. Para preservar esta cámara, vuelve a escribir antes la imagen de serie {bank:loc} (por ejemplo, desde una copia de seguridad completa de la flash hecha antes del cambio) y luego empieza una ejecución nueva.`,"preserve.image.frameRateRefusal":`{name}: {what}. La ejecución toma de esta ranura el firmware al que aplica el parche, así que se detiene aquí, antes de escribir nada. Para preservar esta cámara, vuelve a escribir antes la imagen de serie {bank:loc} (por ejemplo, desde una copia de seguridad completa de la flash hecha antes del parche de velocidad de fotogramas) y luego empieza una ejecución nueva; después se puede volver a aplicar el parche de velocidad de fotogramas a la imagen de serie.`,"preserve.image.otherFirmware":`contiene el firmware {image}, no el {camera} que ejecuta la cámara`,"preserve.image.otherFirmwareRefusal":`{name}: contiene el firmware {image}, no el {camera} que ejecuta la cámara, así que esta ejecución no tiene ahí ninguna imagen a la que aplicar el parche y se niega antes que escribir sobre ella.`,"preserve.image.noImage":`no se deriva de ella ninguna imagen a la que la ejecución pueda aplicar el parche ({error})`,"preserve.gate.runDone":`esta ejecución ha terminado: se completaron todos los pasos (ejecución {run})`,"preserve.gate.stepDone":`{step} ya está hecho en esta ejecución (terminó el {finished}); la reanudación continúa en {next}`,"preserve.gate.stepDoneUnknownTime":`{step} ya está hecho en esta ejecución (terminó en un momento desconocido); la reanudación continúa en {next}`,"preserve.gate.backupRerun":`la copia de seguridad no se puede repetir: esta ejecución ya completó {steps} y su paso siguiente es {next}; usa --resume`,"preserve.gate.powerCycle":`el intento anterior de copia de seguridad falló, y hay que APAGAR Y VOLVER A ENCENDER la cámara antes de repetir este paso: un nuevo intento en el mismo arranque puede leer bytes viejos o en blanco (medido: una copia de seguridad repetida leyó la palabra de arranque del bootloader en lugar del registro de configuración de arranque). Apaga la cámara y vuelve a encenderla (desconéctala y vuelve a conectarla, o usa su interruptor), luego vuelve a ejecutar la copia de seguridad y confirma el apagado cuando se te pida: la ejecución no puede verlo. El fallo registrado: {error}`,"preserve.gate.noErrorText":`(sin texto de error)`,"preserve.gate.patchAfterBackup":`{step} se ejecuta después de la copia de seguridad: la ejecución toma el volcado de todas las regiones que puede leer el plan de serie y lo guarda ANTES de que pase nada más; esa copia de seguridad es la única copia de esta cámara. Ejecuta antes el paso de copia de seguridad.`,"preserve.gate.commitAfterBackup":`{step} se ejecuta después de la copia de seguridad (consulta el paso «Parche»)`,"preserve.gate.commitAfterPatch":`{step} se ejecuta después del paso «Parche», que registra lo que transfiere`,"preserve.gate.commitNeedsPatch":`{step} necesita el parche {banks:gen}, y el paso «Parche» no registró ninguno: vuelve a ejecutar el paso «Parche»`,"preserve.gate.commitFiles":`{step} necesita los archivos de la copia de seguridad en la carpeta de la ejecución y faltan: {files}. Sin ellos, una escritura no tiene de dónde restaurar, así que se niega`,"preserve.gate.drainNoCommit":`{step} lee el chip CON EL PARCHE a través de la ventana ampliada, y esta ejecución no tiene ninguna escritura completada: la lectura completa se atascaría en una cámara de serie. Ejecuta antes la escritura (o reanuda en ella), o salta de forma explícita (allowJump) si la escritura se hizo sin su punto de control.`,"preserve.gate.drainRefused":`el paso de lectura completa se niega en {build}: {note}`,"preserve.gate.detectedBuild":`la compilación detectada`,"preserve.gate.drainHazard":`el paso de lectura completa se niega en {build}: iniciar la lectura completa en el firmware sin parche de esta compilación bloquea la cámara (lee desde un valor que no es una dirección de la flash; medido en el emulador: se entregaron 32 KB y luego la cámara falló). El cambio que hace segura la lectura está en {sites}, y no está entre los cambios que esta ejecución registró para {bank:acc}: ejecuta el paso «Parche» (y completa la escritura) antes de la lectura completa.`,"preserve.gate.drainFiles":`{step} necesita {files} (el volcado entregado se procesa después con la captura de cada ranura escrita) y no está en la carpeta de la ejecución`,"preserve.gate.restoreNoCommit":`{step} vuelve a poner las ranuras originales encima del parche, y esta ejecución no tiene ninguna escritura completada: no hay nada que deshacer. Ejecuta antes la escritura (o reanuda en ella), o salta de forma explícita (allowJump) para restaurar una cámara que ya tiene el parche.`,"preserve.gate.restoreNeedsPatch":`{step} necesita el resumen del parche de cada ranura escrita (por la longitud transferida): ejecuta antes el paso «Parche»`,"preserve.gate.restoreNoForm":`el paso de restauración se niega en {build}: ninguna forma del firmware original pasa la propia comprobación de la cámara y a la vez se almacena como los bytes originales; la suma de comprobación del firmware original es 0xB7AB9D17 (medido), no el 0xFFFF que exige la cámara. Esta ejecución termina con la imagen completa en la mano y con el parche puesto; el contenido original solo se puede volver a poner con un programador de toda la flash.`,"preserve.gate.restoreFiles":`{step} necesita {files} (el original de cada ranura escrita, del paso de copia de seguridad) y no está en la carpeta de la ejecución`,"preserve.gate.verifyNoRestore":`{step} compara un arranque nuevo con la copia de seguridad, y esta ejecución no tiene ninguna restauración completada: una ranura con el parche aparecería como diferencias. Ejecuta antes la restauración (o reanuda en ella), o salta de forma explícita (allowJump) si la restauración se hizo sin su punto de control.`,"preserve.gate.verifyNeedsBackup":`{step} necesita {file} (la referencia de la comparación) y no está en la carpeta de la ejecución`,"preserve.gate.needsBanks":`{step} necesita las ranuras que leyó el paso de copia de seguridad, y el estado no tiene ninguna`,"preserve.gate.noBanks":`no hay ranuras elegidas para esta ejecución: {what}`,"preserve.gate.bankRefused":`no se puede escribir {bank:loc}: {why}`,"preserve.gate.recoveryOnly":`el parche de esta compilación solo arranca desde la ranura de recuperación R: {note}. La ejecución escribiría {bank:loc}, desde donde el bootloader nunca lo ejecuta`,"slots.image.tooSmall":`el archivo es demasiado pequeño para contener una cabecera de imagen`,"slots.image.notWordSized":`el tamaño de la imagen debe ser múltiplo de 4 (tiene {size} B)`,"slots.image.tooLong":`la imagen ocupa {size} B; el bootloader rechaza cualquier header.length >= {limit}, así que nunca arrancaría`,"slots.image.noHeader":`no hay cabecera de imagen en {at} (número mágico {magic}, se esperaba {expected}): tiene que ser una imagen de firmware de Seek descifrada, no una ranura cifrada ni un volcado de la flash`,"slots.image.stackOutside":`el puntero de pila inicial {address} no está en la SRAM del LPC43xx: esto no parece descifrado`,"slots.image.stackUnaligned":`el puntero de pila inicial {address} no está alineado a palabra`,"slots.image.notThumb":`el vector de reinicio {address} no es una dirección Thumb`,"slots.image.noKeyPair":`el nombre de este archivo no lleva su par de claves, y ni el par de esta cámara ni un par de aplicación decodificado aparece en la imagen exactamente una vez, así que no hay forma de saber para qué claves se creó la imagen. Los archivos descifrados salen con un nombre que incluye las claves que contienen.`,"slots.image.keyMismatch":`el nombre del archivo indica la clave A {keyA} y la clave B {keyB}, pero {mismatch}. Las dos claves deben estar presentes, exactamente una vez cada una.`,"slots.image.keyInHeader":`esta imagen guarda una clave en {at}, dentro de la ventana de cabecera sin cifrar: se rechaza aplicarle el parche`,"slots.image.keysOverlap":`la clave A y la clave B del nombre del archivo corresponden a bytes que se solapan en {at} y {other}: tienen que ser dos valores distintos de 16 bytes`,"slots.image.retargetLost":`después de readaptarla, la imagen no lleva el par de claves de esta cámara exactamente una vez: se rechaza crear unos datos con los que el bootloader no podría cifrar las actualizaciones posteriores`,"slots.image.noStageKey":`la imagen no lleva ningún par de claves de la línea de 2016, así que no hay clave de transferencia con la que codificarla`,"slots.image.ffSumNoKeys":`esta imagen tiene la suma de palabras 0xFFFF de la FF de 16 Hz, pero no lleva el par de claves de 1.3.0.8-FF (las dos mitades, una vez cada una), así que no se puede crear su forma de transferencia. No se escribió nada.`,"slots.image.ffNotPlain":`esta es la imagen 1.3.0.8 FF (16 Hz), que se transfiere en su propia forma con la clave A (ff-form.ts), no como imagen sin cifrar. No se escribió nada.`,"slots.plan.otherFirmware":`el plan se creó para el firmware {firmware}, pero el análisis lee {version}. El plan está desfasado; vuelve a crearlo. No se escribió nada.`,"slots.plan.otherFirmwareUnknown":`el plan se creó para un firmware de versión desconocida, pero el análisis lee {version}. El plan está desfasado; vuelve a crearlo. No se escribió nada.`,"slots.plan.otherCamera":`el plan se creó para la cámara {planSerial}, pero el análisis lee {serial}. Se rechaza escribirlo aquí. No se escribió nada.`,"slots.plan.cameraUnknownSerial":`de número de serie desconocido`,"slots.plan.unknownSerial":`un número de serie desconocido`,"slots.plan.otherAddress":`el plan apunta a {address}, pero {name:acc} de esta compilación está en {at}`,"slots.plan.notRead":`el análisis ya no lee {name:acc}. No se escribió nada.`,"slots.plan.edited":`la suma de comprobación del plan no coincide con sus datos, así que el plan se editó. No se escribió nada.`,"slots.plan.outsideBank":`los datos ocupan {size} B, más que {name:acc}`,"slots.plan.riskAck":`{risk}. Para escribirla hace falta acknowledgeRisk: true. No se envió nada.`,"slots.plan.plainStaging":`esta cámara no puede recibir desde aquí una imagen transferida sin cifrar: {reason}. No se escribió nada.`,"slots.plan.noKeyTable":`el análisis no identifica la tabla de claves del bootloader de esta cámara, así que la imagen no se puede readaptar a ella`,"slots.commit.unread":`no se pudo leer el estado de la confirmación después de CompleteMemoryUpgrade, así que {name:acc} puede estar escrita en parte. Vuelve a leer las ranuras antes de hacer nada más, y conserva tu volcado.`,"slots.commit.refused":`la cámara rechazó la escritura {name:loc} al confirmarla, con {status}: {cause}. No se escribió nada; la ranura no ha cambiado. Vuelve a leer las ranuras antes de hacer nada más.`,"slots.commit.eraseStage":`CompleteMemoryUpgrade devolvió {status} ({cause}) para {name:acc}: no se programó nada, pero el borrado puede haber empezado, así que la ranura puede estar borrada en parte. Vuelve a leer las ranuras antes de hacer nada más, y conserva tu volcado.`,"slots.commit.partial":`CompleteMemoryUpgrade devolvió {status} ({cause}): {name:acc} puede estar escrita en parte. Vuelve a leer las ranuras antes de hacer nada más, y conserva tu volcado.`,"slots.commit.stagingStatus":`la cámara indicó {status} al transferir los datos {name:dat}, en el desplazamiento {offset}; se interrumpió antes de CompleteMemoryUpgrade, así que no se escribió nada en la flash`,"commit.cause.badChecksum":`la suma de comprobación de la transferencia no coincidía con los bytes transferidos`,"commit.cause.unsupported":`la imagen no se descifró con las claves de la cámara, o el tipo de datos se rechaza`,"commit.cause.acceptance":`su comprobación rechazó la imagen antes de borrar nada (la comprobación depende de la compilación)`,"commit.cause.notArmed":`no se había abierto ninguna actualización de ranura`,"commit.cause.eraseFailed":`falló la etapa de borrado`,"commit.cause.programFailed":`falló la etapa de programación`,"commit.cause.verifyFailed":`falló la etapa de verificación`,"commit.cause.unknown":`un estado que aquí no se conoce`,"copy.refused.ontoItself":`{name:ins} no se copia sobre sí misma. No se escribió nada.`,"copy.refused.source":`{why}. No se escribió nada.`,"copy.refused.noPlain":`{name:ins} no tiene ninguna imagen descifrada que copiar. No se escribió nada.`,"restore.refused.zipUnreadable":`{file} es un ZIP que aquí no se puede leer ({error}). No se escribió nada.`,"restore.refused.noWholeFlash":`{file} no contiene una flash completa. Se acepta un ZIP cuando es un archivo de ejecución de Preserve que contiene {preserve} (una vez ejecutado su paso de volcado completo), un zip de «Volcar y descifrar 4.x/Nano» ({dump}) o un zip de «Volcar todos los selectores» ({selectors}); este ZIP contiene {names}. No se escribió nada.`,"restore.refused.noWholeFlashPatched":`{file} no contiene una flash completa. Se acepta un ZIP cuando es un archivo de ejecución de Preserve que contiene {preserve} (una vez ejecutado su paso de volcado completo), un zip de «Volcar y descifrar 4.x/Nano» ({dump}) o un zip de «Volcar todos los selectores» ({selectors}); este ZIP contiene {names}. Su {patched} es la flash con el parche temporal de la ejecución, así que no se acepta. No se escribió nada.`,"restore.refused.zipEmpty":`nada`,"restore.refused.wrongSize":`una copia de seguridad completa de la flash ocupa {full} B (4 MB, el chip entero que lee un J-Link); {file} ocupa {size} B. No se escribió nada.`,"restore.refused.noBank":`el plan de esta compilación no tiene {bank:acc}. No se escribió nada.`,"restore.refused.outsideFlash":`{name:ins} no está dentro de una flash de 4 MB. No se escribió nada.`,"restore.refused.gap":`el volcado del que procede {file} no leyó {where}: según su manifest.json, {address} es un hueco. No hay ninguna imagen que restaurar. No se escribió nada.`,"restore.refused.gapReason":`el volcado del que procede {file} no leyó {where}: según su manifest.json, {address} es un hueco ({gap}). No hay ninguna imagen que restaurar. No se escribió nada.`,"restore.refused.gapFill":`el volcado del que procede {file} no leyó {where}: según su manifest.json, {address} es un hueco, rellenado con {fill}. No hay ninguna imagen que restaurar. No se escribió nada.`,"restore.refused.gapReasonFill":`el volcado del que procede {file} no leyó {where}: según su manifest.json, {address} es un hueco ({gap}), rellenado con {fill}. No hay ninguna imagen que restaurar. No se escribió nada.`,"restore.refused.empty":`{where} está vacía: todos los bytes son 0xFF. Una escritura programa una imagen y no puede dejar una ranura borrada, así que una ranura vacía no se puede restaurar con una escritura. No se escribió nada.`,"restore.refused.fill":`{where} contiene {fill} en todos los bytes, el relleno que escribe el volcado donde no leyó nada: el volcado no leyó esta ranura. No hay ninguna imagen que restaurar. No se escribió nada.`,"restore.refused.notDecrypted":`{where} no se puede restaurar desde este archivo: {why}. No se escribió nada.`,"support.noWriteArm":`esta compilación no tiene apertura de escritura para la ranura`,"support.noStagingEmpty":`esta compilación no tiene forma de transferencia, así que no se escribe en una ranura vacía`,"support.buildUnknown":`la compilación es desconocida`,"support.unverifiedStaging":`esta compilación pertenece a la línea bloqueada 0.x/1.x, pero no es una de las compilaciones con las que se midieron las tablas de parches de preservación (0.8.0.0 .. 1.3.0.8 y 1.0.3.0 / 1.0.3.2), así que no se conoce la forma de transferencia de sus ranuras y no se escribe nada`,"support.unknownFamily":`no se conoce la familia de la cámara, así que tampoco la clave con la que se escriben sus ranuras, y una cámara acepta una ranura escrita con la clave equivocada y luego no arranca desde ella. Vuelca y descifra esta cámara, identifícala a partir del volcado y luego indica su familia con --family.`,"support.noReadCommand":`el firmware anterior a 0.8.0.0 no tiene manejador de lectura para GetFeaturedFirmwareData, el comando con el que un volcado lee la flash. En 0.7.0.7 y 0.7.0.8 está en la tabla de métodos RPC en 0x4F, pero registrado solo como escritura (manejador de escritura), así que la lectura control-IN que envía un volcado no se puede atender (la ejecución de preservación lee esas dos compilaciones mediante el wire id 0x58, GetFeaturedData); antes de 0.7.0.7 el wire id 0x4F es UploadFirmwareRowSize, y en 0.3.0.1 el wire id 0x52 (con el que abre un volcado) es EnterBootloaderMode en lugar de BeginFirmwareUpgrade: la cámara sigue en su aplicación, pero cada apertura fija un destino en la flash y prepara la etapa de actualización de firmware de esa compilación (GetErrorCode lee entonces 0x00400000), que no es una ventana de lectura. Obtenido de las propias tablas de métodos de las imágenes, las dos columnas de manejadores; consulta test/firmware/facts.json.`,"support.noWritePath":`estas compilaciones reciben el firmware nuevo con una secuencia de actualización más antigua que esta herramienta no envía, y sus ranuras nunca se mapearon, así que no se escribe nada.`,"support.versionUnread":`no se pudo leer la versión de firmware, así que no se conocen la compilación, sus ranuras ni su forma de transferencia; en ella no se lee ni se escribe nada`,"support.versionNotDotted":`la versión de firmware «{version}» no es una versión con puntos, así que no se conocen la compilación, sus ranuras ni su forma de transferencia; en ella no se lee ni se escribe nada`,"support.olderThanFirst":`el firmware {version} es anterior a {first}: su tabla RPC no tiene manejador de lectura para GetFeaturedFirmwareData, el comando que envía una lectura de ranura, así que no se le envía ni lectura ni escritura (early-compact tiene los indicios)`,"support.modernOnLocked":`la familia modern-4x cubre 2.x, 4.x, 10.x, 42.x y 44.x; {version} pertenece a la línea bloqueada 0.x / 1.x, que necesita legacy-auth o compact-2016`,"support.lockedOnModern":`la familia legacy-auth cubre la línea bloqueada 0.x / 1.x; {version} pertenece a la línea moderna, que necesita modern-4x`,"support.notCompactPro":`la familia compact-2016 cubre la línea 1.0.3.x de la Compact PRO; {version} no pertenece a ella`,"support.earlyCompact":`la familia early-compact solo cubre las compilaciones anteriores a {first}, y {version} se lee con legacy-auth`,"support.generic":`la familia de la cámara no está identificada (familia generic), así que no se conocen la disposición de las ranuras ni la forma de transferencia; identifica la cámara antes de leer o escribir una ranura`,"support.noPlan":`no existe ningún plan de ranuras para la familia {family}: no se conocen la disposición de sus ranuras ni su forma de transferencia`,"support.noArmPlain":`la tabla de esta compilación no abre el modo {mode} en {address} por el canal simple`,"support.noArmToken":`la tabla de esta compilación no abre el modo {mode} en {address} por el canal con token`,"support.windowElsewhere":`la ventana de preservación {bank:gen} está en {at}, no en {address}`,"support.noDumpWindow":`la tabla BeginFirmwareUpgrade de esta compilación no tiene ninguna ventana en {address} para {bank:acc}`,"support.capabilityRefused":`{family} no admite {capability}: {reason}`,"support.capability.dump":`el volcado`,"support.capability.allSelectors":`«Volcar todos los selectores»`,"support.capability.decrypt":`el descifrado`,"support.capability.deviceInfo":`la lectura completa de la pestaña «Información»`,"support.capability.flash":`la escritura de ranuras`,"slots.unread.noWindow":`{name:ins} en {address} no se puede leer en esta compilación: su tabla de selectores no tiene ahí ninguna ventana, así que no se abrió nada para ella`,"slots.unread.missing":`{name:ins} falta en el análisis de la cámara`,"slots.unread.notRead":`{name:ins} no se leyó`,"slots.refused.nothingWritten":`{refusal}. No se escribió nada.`,"slots.refused.versionUnknown":`el análisis no dice qué firmware ejecuta la cámara, y los comandos de ranura significan cosas distintas en compilaciones distintas. Vuelve a leer la información del dispositivo.`,"slots.refused.versionUnknownWrite":`el análisis no dice qué firmware ejecuta la cámara. No se escribió nada.`,"slots.refused.emptyInput":`la entrada está vacía`,"slots.refused.emptyNotWritable":`{name:ins} está vacía y no se puede escribir en esta compilación: {reason}`,"slots.refused.noRaw":`{name:ins} no puede recibir bytes sin procesar en esta compilación: {reason}`,"slots.refused.noPlain":`{name:ins} no puede recibir una imagen descifrada en esta compilación: {reason}`,"slots.refused.noStaging":`{name:ins} no tiene forma de transferencia en esta compilación, así que no se puede codificar una imagen para ella`,"slots.refused.rawTooLong":`{size} B es más que {name:acc} ({bankSize} B)`,"slots.refused.imageTooLong":`la imagen ocupa {size} B, más que {name:acc} ({bankSize} B)`,"preserve.routeNote.recoveryOnly":`el bootloader de 2014 no acepta la suma de comprobación de esta compilación en la ranura A ni en la B, y arranca la ranura de recuperación R (0x14070000) sin comprobarla, así que el parche se escribe en la ranura de recuperación R y en ningún otro sitio`,"preserve.refused.recoveryOnly":`esta compilación solo arranca desde la ranura de recuperación R: {note}`,"decryptFile.wrongSize":`una ranura de firmware ocupa {size} B ({kib} KB); este archivo ocupa {count} B`,"decryptFile.erasedBank":`vacía, no hay nada que descifrar: los {size} B se leen como 0xFF (una ranura borrada)`,"decryptFile.erasedHeader":`borrada: la ventana de cabecera es toda 0xFF, así que la ranura no contiene ninguna imagen; no se descifra nada`,"decryptFile.noHeader":`no hay cabecera de imagen (número mágico {magic}), así que no hay imagen que descifrar`,"decryptFile.lengthOutOfRange":`header.length {length} está fuera de rango; no hay imagen que descifrar`,"decryptFile.ffKeyB":`descifrados {size} B con la clave B de FF 1.3.0.8: la imagen se almacena como la imagen XOR el flujo de clave de su bloque de claves 1, con la ventana de cabecera literal`,"decryptFile.notRecovered":`clave no recuperada: la imagen se descifra con un vector de reinicio que no es una entrada de Cortex-M (clave {check}); no se descifra nada`,"decryptFile.storedPlain":`almacenada sin cifrar: la ranura contiene la imagen tal como se ejecuta (la cadena sin cifrar de 2014, un flujo de clave identidad), así que no hay clave y la imagen descifrada es la propia imagen`,"decryptFile.decrypted":`descifrados {size} B con la clave recuperada de esta ranura ({check})`,"decryptFile.decryptedNamed":`descifrados {size} B con la clave recuperada de esta ranura ({check}; es {key:acc})`,"read.reason.shortRead":`lectura corta ({size} B)`,"read.reason.noParse":`no se pudo interpretar una cabecera de imagen`,"read.reason.noHeader":`no hay cabecera de imagen (número mágico {magic})`,"read.reason.lengthOutOfRange":`header.length {length} está fuera de rango`,"read.reason.stopped":`la lectura de la ranura se detuvo en {count}/{size} B`,"read.reason.notInPlan":`no se puede leer en el firmware {version}: su plan ({table}) no tiene ninguna ventana en {address}, así que no se abrió nada para ella`,"read.reason.notInPlanUnknown":`no se puede leer en un firmware de versión desconocida: su plan ({table}) no tiene ninguna ventana en {address}, así que no se abrió nada para ella`,"read.reason.staleDescriptor":`la ventana entregó los bytes de un descriptor de lector caducado (la palabra 0 {word} con reinicio {hex} es la tabla de vectores de 0x14000000, no el contenido de esta ranura), así que no se analizó nada de ella: {remedy}`,"read.reason.spentReader":`no se pudieron leer las ranuras de la cámara: {remedy}`,"read.spentRemedy":`puede que el lector de ventanas se haya agotado en este arranque; apaga la cámara, vuelve a encenderla y vuelve a intentarlo`,"checkKey.unnamed.wordNotRead":`no se pudo leer la palabra de ranura activa de la cámara (fw info roots, selector 10)`,"checkKey.unnamed.wordNamesNoBank":`la palabra de ranura activa de la cámara es {word}, que no nombra ninguna ranura`,"checkKey.unnamed.cfg0NotRead":`no se leyó la palabra de configuración de arranque, así que no se sabe si el bootloader comprobó {bank:acc} antes de entrar en ella`,"checkKey.unnamed.noZeroSum":`la cámara indica que entró {bank:loc}, pero {bank:acc} no se descifra con una suma de palabras cero en esta lectura`,"checkKey.unnamed.noZeroSumUnchecked":`la cámara indica que entró {bank:loc}, que la palabra de configuración de arranque {word} deja para el final, así que el bootloader entró en ella sin su comprobación, pero {bank:acc} no se descifra con una suma de palabras cero en esta lectura`,"report.detected":`{family} (puntuación {score} tras la lectura, según los indicios de abajo)`,"report.detectedAmbiguous":`{family} (puntuación {score} tras la lectura, según los indicios de abajo; ambiguo)`,"report.cell.yes":`sí`,"report.cell.no":`no`,"report.cell.notApplicable":`n/d`,"report.cell.unknown":`desconocido`,"report.cell.recoveryOnly":`solo recuperación`,"report.keyRow.whitening":`K de blanqueo`,"report.keyRow.store":`clave de almacenamiento`,"report.keyRow.check":`clave de comprobación`,"report.keyRow.table":`tabla de claves`,"report.keyRow.keys":`claves`,"report.keyRow.a":`clave A`,"report.keyRow.b":`clave B`,"report.keyRow.tableAt":`tabla en`,"report.key.notIdentified":`(sin identificar)`,"report.key.candidates":{one:`{count} candidata, ninguna confirmada`,many:`{count} de candidatas, ninguna confirmada`,other:`{count} candidatas, ninguna confirmada`},"report.key.tableAt":`{offset} en el bloque del bootloader, confirmada con una ranura`,"report.key.plainChain":`no hace falta ninguna: las ranuras se almacenan como firmware sin cifrar, así que una ranura se lee y se escribe tal cual`,"report.key.tableRefused2016":`no se leyó: el bloque del bootloader (0x14000000) se rechaza en todos los canales en esta línea de firmware`,"report.checkKey.named":`{key} {hex}{pair}`,"report.checkKey.namedFrom":`{key} {hex}{pair}, identificada a partir {bank:gen}, la ranura en la que la cámara indica que entró tras la comprobación del bootloader`,"report.checkKey.inferredFrom":`{key} {hex}{pair}, deducida {bank:gen}, la ranura en la que la cámara indica que entró: el bootloader entra en esa ranura sin su comprobación, y la ejecuta con la clave con la que comprueba las demás ranuras`,"report.checkKey.pair":` (bloque 1 de {pair})`,"keyPair.cp103":`el par de 9 Hz de la Compact PRO 1.0.3.x`,"keyPair.cp1032ff":`el par FF de la Compact PRO 1.0.3.x`,"report.checkKey.notNamed":`sin identificar: {why}`,"report.checkKey.couldNotName":`la lectura no pudo identificarla`,"report.storeKey.checkKeyUnnamed":`la clave con la que su bootloader comprueba una ranura (no identificada en esta lectura): la aplicación almacena con esa clave cada ranura que escribe`,"report.storeKey.checkKey":`{key}: la aplicación almacena cada ranura que escribe con la clave que comprueba su bootloader`,"report.storeKey.unknown":`desconocida: no se leyó el bloque del bootloader que contiene la posición de la clave propia del dispositivo`,"report.storeKey.keyBUnidentified":`clave B (no hay clave propia del dispositivo programada; la propia clave B no está identificada)`,"report.storeKey.keyB":`clave B (no hay clave propia del dispositivo programada)`,"report.staged.plain":`transferida sin cifrar (la imagen tal cual, sin clave)`,"report.staged.slotKeystream":`transferida con el bloque de claves 0 propio de su imagen`,"report.staged.keyA":`transferida con claves derivadas de la ranura de arranque y de la aplicación en ejecución`,"report.staged.ffVendor":`transferida como la app del fabricante transfiere la imagen FF de 16 Hz (la imagen XOR su propio bloque de claves 0), y almacenada por la cámara con la clave B`,"progress.backupBlock":`Copia de seguridad: bloque {address}`,"progress.backupDone":`Copia de seguridad: todos los bloques leídos`,"progress.checkBlock":`Comprobación: bloque {address}`,"progress.checkDone":`Comprobación: todos los bloques leídos`,"progress.writingBank":`Escribiendo {bank:loc}`,"progress.restoringBank":`Restaurando {bank:acc}`,"progress.staged":`{label}: transferidos {done}/{total} B`,"progress.wholeFlash":`Lectura completa: {got}/{total} B`,"progress.readWindow":`lectura {address} subcmd={subcmd}...`,"progress.readWindowAuth":`lectura {address} subcmd={subcmd} (auth)...`,"progress.windowsRead":`Hecho: {ok}/{total} ventanas leídas.`,"progress.readingBank":`Leyendo {bank:acc}...`,"progress.analysing":`Analizando...`,"progress.probeSelector":`probando el selector {selector}...`,"progress.selectorsArmed":`Hecho: {armed}/{span} selectores abiertos, {withData} con datos.`,"progress.recoveringKey":`descifrado: recuperando la clave de {address}...`,"slots.window.unread":`{bank:ins} {address} (subcmd {subcmd}) no se pudo leer: {error}`,"slots.read.refusedBuild":`se rechaza leer las ranuras de firmware: {reason}. No se envió nada más que la lectura de la versión, así que no se tocó ninguna ranura.`,"slots.backup.notSaved":`la copia de seguridad {file} no se guardó, así que no se escribió nada. Una escritura nunca se ejecuta sin guardar antes su copia de seguridad; vuelve a intentarlo cuando se pueda guardar.`,"slots.backup.notSavedWhy":`la copia de seguridad {file} no se guardó ({error}), así que no se escribió nada. Una escritura nunca se ejecuta sin guardar antes su copia de seguridad; vuelve a intentarlo cuando se pueda guardar.`,"usb.speed.high":`alta (480 Mbit/s)`,"usb.speed.full":`completa (12 Mbit/s)`,"usb.speed.code":`código {code}`},shared:{"runPanel.percent":`{value} %`,"runPanel.progressLabel":`{label}: progreso`,"runPanel.logLabel":`{label}: registro`,"runPanel.trimmed":{one:`… {count} línea anterior recortada`,many:`… {count} de líneas anteriores recortadas`,other:`… {count} líneas anteriores recortadas`},"runPanel.lineCount":{one:`{count} línea`,many:`{count} de líneas`,other:`{count} líneas`},"status.idle":`En espera.`,"status.cancelled":`Cancelado.`,"status.cancelling":`Cancelando…`,"status.failedSeeLog":`Error: consulta el registro de arriba.`,"cameraLock.inUseElsewhere":`La cámara se está usando en otra pestaña o ventana: termina allí o ciérrala primero.`,"backup.downloadNote":`El zip se descarga automáticamente, antes de enviar nada.`,"device.none":`Ningún dispositivo seleccionado.`,"device.disconnected":`Dispositivo desconectado.`,"device.revoked":`Permiso revocado.`,"device.unknownProduct":`producto desconocido`,"device.unknownVendor":`fabricante desconocido`,"hint.udev":`En Linux, la cámara necesita una regla udev antes de que el navegador pueda abrirla:

{rule}

Luego desconecta la cámara y vuelve a conectarla. Las versiones Snap y Flatpak de Chromium suelen estar aisladas de los dispositivos USB; la versión .deb o .rpm es la fiable.`,"hint.windows":`Windows necesita que el controlador WinUSB esté asignado a la cámara antes de que cualquier navegador pueda llegar a ella. Usa Zadig (https://zadig.akeo.ie/): Options → List All Devices, elige la entrada con el nombre de tu cámara (por ejemplo, «CompactPRO FF»), elige WinUSB y haz clic en Replace Driver.`,"hint.holding":`Otro programa o un controlador del sistema está usando la cámara: solo un proceso puede usar la interfaz USB a la vez. Cierra cualquier otra cosa que se comunique con ella y luego desconecta la cámara y vuelve a conectarla.`,"hint.recipientFallback":`O pon recipient en «device» en las opciones de lectura, que no necesita reclamar la interfaz.`,"hint.optionsInvalid":`Abre «Opciones» y revisa la nota bajo los campos para ver el intervalo de cada uno.`,"hint.usbTimeout":`La cámara aceptó la petición y nunca respondió. Desconéctala y vuelve a conectarla, y luego prueba con un chunk más pequeño (64 es el valor que funciona en todas partes).`,"hint.usbStalled":`La cámara rechazó la petición. Normalmente esto significa que su firmware no la admite. La página pregunta a la cámara de qué familia es antes de leer nada, así que las peticiones que se siguen rechazando se hicieron para la familia que indicó la propia cámara. Comprueba la versión de firmware en la pestaña «Información».`,"hint.usbNotOpen":`Otro programa o un controlador del sistema está usando la cámara. Ciérralo, o pon recipient en «device» en las opciones de lectura, que no necesita reclamar la interfaz.`,"hint.usbTransferFailed":`Desconecta la cámara, vuelve a conectarla y vuelve a intentarlo.`,"hint.deviceMode":`La cámara no quiso salir del modo de imagen. Desconéctala, espera a que se apague del todo y vuelve a conectarla.`,"hint.deviceWindow":`El mapa de selectores que usa esta familia no coincidió con la cámara. En la pestaña 4.x/Nano, abre «Opciones» y ejecuta «Volcar todos los selectores» para ver lo que ofrece realmente la cámara.`,"hint.deviceVersionUnknown":`No se envió nada que pudiera cambiar la cámara. Desconéctala, vuelve a conectarla, deja que termine de arrancar y vuelve a intentarlo; una cámara que indica su versión de firmware se lee con normalidad.`,"hint.imageMalformed":`El archivo no es una imagen de firmware de Seek descifrada.`,"hint.imageUnsupported":`Esta imagen no se puede preparar para la cámara tal como está.`,"hint.imageKeyTable":`La imagen no lleva el par de claves que indica su nombre de archivo. Usa el archivo descifrado exactamente como lo escribió el volcado, con su nombre incluido.`,"hint.flashRefused":`No se escribió nada en la cámara.`,"hint.familyUnsupported":`No se leyó ni se escribió nada. Cada pestaña cubre un intervalo de versiones de firmware: las cámaras 0.x y 1.x van a «Volcar y descifrar 0.x/1.x», y las 4.x y Nano a «Volcar y descifrar 4.x/Nano». La pestaña «Información» dice a qué pestaña va la cámara.`,"hint.firmwareTooOld":`Ninguna familia de firmware puede leer aquí esta compilación: su firmware no tiene manejador de lectura para el comando con el que esta pestaña lee la flash, así que no se le envió nada que pudiera malinterpretarse. Una Compact con 0.7.0.7 o 0.7.0.8 se puede leer en «Volcar y descifrar 0.x/1.x». Un volcado hecho con un programador SPI o por SWD/J-Link se puede descifrar igualmente en esta página, en «Descifrar archivo/ranura».`,"hint.powerCycle":`En este asistente: desconecta la cámara y vuelve a conectarla, pulsa «Conectar dispositivo» y elígela, y luego vuelve a empezar el mismo paso. La ejecución sigue cargada aquí: no hay nada que reanudar.`,"deviceInfo.running":`Firmware en ejecución`,"deviceInfo.version":`Versión`,"deviceInfo.family":`Familia de firmware`,"deviceInfo.build":`Compilación`,"deviceInfo.bootloader":`Bootloader`,"deviceInfo.platform":`Plataforma`,"deviceInfo.serial":`Número de serie`,"deviceInfo.usbLink":`Enlace USB`,"deviceInfo.bootConfig":`Config. de arranque`,"deviceInfo.bootedFrom":`Arrancó desde`,"deviceInfo.nextStart":`Próximo arranque`,"deviceInfo.upgradeTarget":`Destino de actualización (su propia actualización)`,"deviceInfo.bankAt":`{bank} en {address}`,"deviceInfo.perDeviceKey":`Clave propia del dispositivo`,"deviceInfo.notProgrammed":`no programada: la cámara recurre a la clave B`,"deviceInfo.keysTitle":`Claves leídas de esta cámara`,"deviceInfo.foundAt":`Encontrada en`,"deviceInfo.flashOffset":`desplazamiento {offset} en la flash`,"deviceInfo.keyA":`Clave A`,"deviceInfo.keyB":`Clave B`,"deviceInfo.orphan":{one:`**{banks:ins} contiene una imagen de firmware válida cifrada con una clave que el bootloader de esta cámara no conoce.** La imagen está intacta y su suma de comprobación es correcta, pero el bootloader solo prueba {storeKey:acc} y la clave A cuando comprueba una ranura, así que la salta y arranca otra cosa.`,many:`**Estas ranuras contienen una imagen de firmware válida cifrada con una clave que el bootloader de esta cámara no conoce: {banks:acc}.** Las imágenes están intactas y su suma de comprobación es correcta, pero el bootloader solo prueba {storeKey:acc} y la clave A cuando comprueba una ranura, así que las salta y arranca otra cosa.`,other:`**Estas ranuras contienen una imagen de firmware válida cifrada con una clave que el bootloader de esta cámara no conoce: {banks:acc}.** Las imágenes están intactas y su suma de comprobación es correcta, pero el bootloader solo prueba {storeKey:acc} y la clave A cuando comprueba una ranura, así que las salta y arranca otra cosa.`},"deviceInfo.orphanIsTarget":`Esa es la ranura que escribe una actualización. La aplicación que se ejecuta en esta cámara vuelve a cifrar con esa clave desconocida, así que **escribir mediante esta página producirá otra ranura que el bootloader no puede arrancar**: la cámara seguirá ejecutando {bank:acc}. La forma de evitarlo es escribir la ranura directamente con un programador SPI o por SWD/J-Link.`,"deviceInfo.otherBank":`la otra ranura`,"deviceInfo.otherBank:acc":`la otra ranura`,"deviceInfo.otherBank:gen":`de la otra ranura`,"deviceInfo.otherBank:dat":`a la otra ranura`,"deviceInfo.otherBank:loc":`en la otra ranura`,"deviceInfo.otherBank:ins":`La otra ranura`},info:{"status.notRead":`Aún no se ha leído.`,"status.reading":`Leyendo...`,"status.noVersion":`No se indicó ninguna versión.`,"status.tooOld":`Leído. El firmware {version} es anterior a 0.8.0.0: no se leyó nada más.`,"status.read":`Leído. Firmware {version}.`,"read.title":`Leer la cámara`,"read.description":`Solo lectura. Pregunta a la cámara qué ejecuta, cómo arranca, qué claves tiene y qué contiene cada ranura: la misma lectura que seek-fw info. No se escribe nada.`,"read.actions":`Acciones de información`,"read.button":`Leer versión de firmware`,"read.connectFirst":`Primero conecta la cámara arriba y luego pulsa «Leer versión de firmware».`,"read.showDetails":`Mostrar detalles en el registro`,"read.panel":`Versión de firmware`,"result.title":`Lo que indica la cámara`,"result.version":`Versión de firmware`,"result.build":`Compilación`,"result.range":`Intervalo de versiones`,"result.tab":`Pestaña para esta cámara`,"result.rangeLegacy":`0.x / 1.x: las cámaras de 2014 y 2016`,"result.rangeModern":`2.x y posteriores: las cámaras 4.x, Nano y Mosaic`,"result.rangeUnknown":`desconocido`,"result.noVersion":`**La cámara no indicó su versión de firmware.** No se envió nada más. Desconéctala, vuelve a conectarla, deja que termine de arrancar y vuelve a leerla.`,"result.noTab":`Ninguna pestaña lee esta compilación.`,"result.openTab":`Abre <tab>{tab}</tab> para esta cámara. Esa pestaña vuelve a preguntar a la cámara de qué familia es antes de leer nada, y rechaza una cámara que no sea de la familia que cubre.`,"tabs.title":`Para qué sirve cada pestaña`,"tabs.intro":`Cinco pestañas, en este orden. Cada una es una página propia, y la cabecera muestra en cuál estás.`,"tabs.caption":`Las pestañas, lo que hacen, las cámaras que cubren y si escriben`,"tabs.tab":`Pestaña`,"tabs.does":`Qué hace`,"tabs.cameras":`Cámaras`,"tabs.writes":`¿Escribe en la cámara?`,"tabs.info.does":`Lee lo que indica la cámara: su firmware, la familia con la que responde, cómo arranca, sus claves y todas sus ranuras. La misma lectura que seek-fw info. No escribe nada.`,"tabs.info.cameras":`Cualquier cámara Seek que WebUSB pueda abrir.`,"tabs.info.writes":`No.`,"tabs.preserve.does":`Hace una copia completa de la flash de 4 MB de la cámara y guarda un archivo de ejecución después de cada paso. Para leerla entera, aplica durante un rato un parche al firmware, y luego vuelve a poner el firmware original y lo comprueba. Te guía por los pasos de uno en uno.`,"tabs.preserve.cameras":`Cámaras con firmware 0.x y 1.x: las compilaciones Compact de 2014, las compilaciones Compact PRO de 2016 (1.0.3.x) y la compilación Compact 1.3.0.8 FF (16 Hz).`,"tabs.preserve.writes":`Sí, en dos pasos, y cada uno pregunta antes. Deja la cámara como estaba.`,"tabs.v4.does":`Lee toda la flash de una cámara 4.x o Nano y descifra las ranuras de firmware que encuentra. Solo lectura: envía seis comandos de lectura y ninguno de escritura.`,"tabs.v4.cameras":`Cámaras con firmware 4.x (Compact, Compact PRO, Compact XR), Mosaic (10.x y 2.x) y Nano (42.x y 44.x), de 2018 en adelante.`,"tabs.v4.writes":`No.`,"tabs.decrypt.does":`Descifra un archivo que ya tienes: un volcado completo, ranura por ranura, o una sola ranura de firmware de 64 KB. El resultado se puede descargar.`,"tabs.decrypt.cameras":`Ninguna. No usa ninguna cámara, así que funciona sin nada conectado y en cualquier navegador.`,"tabs.decrypt.writes":`No. Solo escribe la descarga.`,"tabs.slots.does":`Lee las tres ranuras de firmware (ranura A, ranura B y ranura de recuperación R), muestra lo que contiene cada una y desde cuál arranca la cámara, y puede volcar o escribir una ranura cada vez.`,"tabs.slots.cameras":`Cámaras con firmware 0.8.0.0 y posteriores.`,"tabs.slots.writes":`Sí, una ranura cada vez, y cada escritura pregunta antes.`,"report.camera":`Cámara`,"report.product":`Producto`,"report.manufacturer":`Fabricante`,"report.serial":`Número de serie`,"report.platform":`Plataforma`,"report.usbLink":`Enlace USB`,"report.noProduct":`(sin cadena de producto)`,"report.none":`(ninguno)`,"report.unreadable":`(ilegible)`,"report.firmware":`Firmware`,"report.running":`En ejecución`,"report.bootloader":`Bootloader`,"report.family":`Familia de firmware`,"report.readUnder":`Leída como`,"report.detected":`Detectada`,"report.boot":`Arranque`,"report.booted":`Ranura de arranque`,"report.lastStart":`Último arranque`,"report.running1308":`En ejecución (1.3.0.8)`,"report.nextStart":`Próximo arranque`,"report.upgradeTarget":`Destino de actualización`,"report.notReplayed":`(no consultado)`,"report.targetConfirmed":`{slot} (confirmado en la comunicación USB)`,"report.buildNotKnown":`no se sabe: {why}. Una imagen FF de 16 Hz necesita que la cámara diga qué compilación ejecuta (la pestaña de ranuras lo pregunta)`,"report.buildWhy":`{build}: {why}`,"report.buildFf":`la compilación 1.3.0.8 FF de 16 Hz`,"report.build8Hz":`la compilación 1.3.0.8 de 8 Hz`,"report.keys":`Claves`,"report.slots":`Ranuras`,"report.slotsCaption":`Cada ranura tal como la encontró la lectura. Solo lectura: la que escribe es la pestaña de ranuras.`,"report.slot":`Ranura`,"report.address":`Dirección`,"report.version":`Versión`,"report.size":`Tamaño`,"report.key":`Clave`,"report.accepts":`Acepta`,"report.footer":`Pie`,"report.bootable":`Arrancable`,"report.bytes":`{count} B`,"report.plaintext":`ninguna (sin cifrar)`,"report.yes":`sí`,"report.no":`no`,"report.notApplicable":`n/d`,"report.slotReason":`{slot}: {reason}`,"report.writing":`Escritura`,"report.noBankWritten":`No se escribe ninguna ranura de esta cámara:`,"report.oneBank.plain":`De una ranura en una: la pestaña de ranuras escribe o parchea una sola ranura de esta cámara cada vez; cada ranura se transfiere sin cifrar (la imagen tal cual, sin clave), y cada escritura pregunta antes.`,"report.oneBank.slotKeystream":`De una ranura en una: la pestaña de ranuras escribe o parchea una sola ranura de esta cámara cada vez; cada ranura se transfiere con el bloque de claves 0 propio de su imagen, y cada escritura pregunta antes.`,"report.oneBank.keyA":`De una ranura en una: la pestaña de ranuras escribe o parchea una sola ranura de esta cámara cada vez; cada ranura se transfiere con claves derivadas de la ranura de arranque y de la aplicación en ejecución, y cada escritura pregunta antes.`,"report.oneBank.ffVendor":`De una ranura en una: la pestaña de ranuras escribe o parchea una sola ranura de esta cámara cada vez; cada ranura se transfiere como la app del fabricante transfiere la imagen FF de 16 Hz (la imagen XOR su propio bloque de claves 0), y la cámara la almacena con la clave B. Cada escritura pregunta antes.`,"report.refusesEvery":`La pestaña de ranuras rechaza todas las ranuras de esta cámara:`},decrypt:{"status.noFile":`No se ha elegido ningún archivo.`,"status.reading":`Leyendo el archivo...`,"status.notUsable":`No es un volcado utilizable.`,"status.building":`Creando el archivo comprimido...`,"status.nothingDecrypted":`No se descifró ninguna imagen: consulta el motivo en el registro. El manifiesto está en tus descargas.`,"status.done":{one:`Hecho: {done}/{count} ranura descifrada. Revisa tus descargas.`,many:`Hecho: {done}/{count} de ranuras descifradas. Revisa tus descargas.`,other:`Hecho: {done}/{count} ranuras descifradas. Revisa tus descargas.`},"offline.title":`Descifrar un volcado que ya tienes`,"offline.description":`Un volcado completo de la flash, descifrado ranura por ranura.`,"offline.intro":`El paso 2 de la pestaña 4.x/Nano ya descifra todo lo que lee, así que solo necesitas esto si tu imagen de la flash viene de otro sitio: una ejecución anterior, J-Link o un programador SPI. El archivo se lee localmente y nunca se sube. **Esta parte funciona en todos los navegadores**, incluidos Safari e iOS, porque no necesita acceso USB.`,"offline.actions":`Acciones de descifrado sin conexión`,"offline.choose":`Elegir archivo de volcado…`,"offline.panel":`Descifrado sin conexión`,"offline.detectedTitle":`Familia de firmware detectada`,"offline.detectedIntro":`No hay ninguna cámara conectada, así que la familia se puntúa a partir de las imágenes del propio archivo. La clave se resuelve igualmente a partir del texto cifrado de cada ranura; esto es lo que da nombre a la familia de firmware en el informe.`,"offline.scoreBasis":`a partir de las imágenes del archivo`,"slot.title":`Descifrar una ranura de firmware`,"slot.description":`Una ranura, desde un archivo: 64 KB, tal como la almacena la cámara.`,"slot.intro":`Elige un archivo que contenga una ranura de firmware: 65 536 bytes, como la guarda un volcado de ranura en la pestaña <link>{tab}</link>, o los 64 KB que hay en la dirección de una ranura en un volcado completo de la flash. La página encuentra la clave a partir de los propios bytes de la ranura, descifra la imagen y te la ofrece para descargar, mostrando la clave, el tamaño y el SHA-256. No se usa ninguna cámara, así que funciona sin nada conectado.`,"slot.refusedIntro":`Un archivo que no sea una ranura, que no contenga ninguna imagen de firmware o que no se descifre se rechaza indicando el motivo. Una ranura borrada lo indica y no tiene nada que descifrar.`,"slot.actions":`Acciones del archivo de ranura`,"slot.choose":`Elegir archivo de ranura…`,"slot.decrypting":`Descifrando {file}…`,"slot.unreadable":`No se pudo leer el archivo.`,"slot.notDecrypted":`Sin descifrar: {file} no es una ranura de firmware que esta página pueda descifrar.`,"slot.nothingWritten":`No se escribió nada en ningún sitio. Elige un archivo de ranura de 64 KB, o un volcado completo en la sección de arriba.`,"slot.erased":`{file} es una ranura borrada.`,"slot.resultTitle":`Ranura de firmware descifrada`,"slot.file":`Archivo`,"slot.fileSize":`Tamaño del archivo`,"slot.fileSha":`SHA-256 del archivo`,"slot.imageVersion":`Versión de la imagen`,"slot.imageSize":`Tamaño de la imagen`,"slot.imageSha":`SHA-256 de la imagen`,"slot.acceptanceSum":`Suma de comprobación`,"slot.notComputed":`no se calcula para esta forma`,"slot.family":`Familia`,"slot.familyDetected":`{name} (detectada a partir de la imagen)`,"slot.familyMismatch":`{name}: la suma no es la que exige esta familia, así que el bootloader no aceptaría la imagen tal como está`,"slot.unknown":`desconocida`,"slot.bytes":`{size} B`,"slot.key":`Clave`,"slot.keyPlain":`ninguna: la ranura contiene la imagen sin cifrar (la cadena sin cifrar de 2014)`,"slot.keyFfB":`clave B del par 1.3.0.8 FF`,"slot.storedAs":`Almacenada como`,"slot.storedAsFfB":`la imagen XOR el flujo de clave de la clave B, con la ventana de cabecera literal`,"slot.keyNone":`ninguna`,"slot.keyNamed":`{key} — {name}`,"slot.keyForm":`Forma de la clave`,"slot.keyFormOnce":`{k}: la propia imagen contiene esta forma una sola vez, y eso la identifica`,"slot.keyFormDefault":`{k}: ninguna forma aparece una sola vez en la imagen, así que se muestra la de la familia por defecto`,"slot.resultActions":`Acciones de la imagen descifrada`,"slot.download":`Descargar {file}`,"slot.downloadFallback":`la imagen descifrada`,"detection.detected":`Detectada`,"detection.score":`Puntuación`,"detection.scoreText":`{score} de 1.00, {basis}`,"detection.readAs":`Leída como`,"detection.summary":`Resumen`,"detection.why":`Por qué:`,"detection.ambiguous":`**Los indicios no permitieron decidir qué familia es.** O la ganadora no puntuó mejor que la alternativa genérica, o la segunda quedó demasiado cerca para decidir. El descifrado no se ve afectado (la clave se resuelve igualmente a partir del texto cifrado), pero la familia que nombra el informe, y todo lo que depende de ella, es una suposición.`},v4:{"status.starting":`Iniciando...`,"status.building":`Creando el archivo comprimido...`,"status.cancelling":`Cancelando: se guardará lo que se haya leído hasta ahora...`,"status.refused":`Rechazado: no se leyó nada. Consulta el mensaje encima del registro.`,"status.sweepDone":`Hecho: {armed}/{total} selectores abiertos, {withData} con datos. Revisa tus descargas.`,"status.sweepDoneCancelled":`Hecho: {armed}/{total} selectores abiertos, {withData} con datos (cancelado). Revisa tus descargas.`,"status.dumpDone":`Hecho: {read}/{expected} ventanas leídas. Revisa tus descargas.`,"status.dumpDoneCancelled":`Hecho: {read}/{expected} ventanas leídas (cancelado). Revisa tus descargas.`,"status.dumpDoneIncomplete":`Hecho: {read}/{expected} ventanas leídas (incompleto: consulta el registro). Revisa tus descargas.`,"refusal.generic":`La cámara no coincidió con la familia 4.x/Nano, y esta pestaña solo lee esa familia. No se leyó nada. Para una cámara 0.x o 1.x (compilaciones de 2014 o 2016), usa «{tab}».`,"refusal.otherFamily":`La cámara parece ser {name} ({id}), no una cámara 4.x/Nano, y esta pestaña solo lee 4.x/Nano. No se leyó nada. Para una cámara 0.x o 1.x (compilaciones de 2014 o 2016), usa «{tab}».`,"refusal.legacyLine":`La cámara ejecuta {version}, una compilación 0.x o 1.x (2014 o 2016), y esta pestaña solo lee 4.x/Nano. No se leyó nada salvo la versión. Para una cámara 0.x o 1.x, usa «{tab}».`,"dump.title":`Volcado`,"dump.actions":`Acciones de volcado`,"dump.start":`Iniciar volcado`,"dump.panel":`Volcado`,"dump.how":"Los dos preguntan primero a la cámara qué firmware ejecuta: su versión, con `{getInfo}` (la única lectura a la que todas las compilaciones de Seek responden igual) y, solo si esa compilación se puede leer por USB, un `{begin}` simple, otro con token y una sola lectura. Así sabe la página de qué familia es la cámara. Esta pestaña solo lee la familia 4.x y Nano. Una cámara que según esas respuestas pertenezca a otra se rechaza antes de leer nada, y la página nombra la pestaña que le corresponde. Una cámara que no indica su versión, o que ejecuta una compilación anterior a 0.8.0.0, no se lee en absoluto, y la página dice por qué.","dump.modes":"**Iniciar volcado** lee todos los bloques a los que llega la tabla de selectores de la propia compilación. **Volcar todos los selectores**, en *Opciones* más abajo, prueba todos los selectores `{begin}` `{first}`–`{last}` y guarda lo que devuelva cada uno: es más lento, pero también captura bloques que el mapa seleccionado omite.","dump.sweep":`Volcar todos los selectores ({first}–{last})`,"dump.sweepNote":`Prueba todos los selectores y guarda lo que devuelva cada uno. Más lento que «Iniciar volcado».`,"output.title":`Lo que obtienes`,"output.intro":"Una sola descarga `{ext}` que contiene:","output.caption":`Archivos dentro del archivo descargado`,"output.file":`Archivo`,"output.what":`Qué es`,"output.flash":`la imagen completa de la flash de 4 MB (el relleno del hueco y el token de desbloqueo, si se usó, están en manifest.json)`,"output.windows":`cada bloque de 64 KB exactamente como llegó por USB`,"output.decrypted":`cada ranura de imagen de firmware, descifrada (si se encontró una clave)`,"output.reports":`informe por ranura: clave, posición de la clave, familia y cifrado, SP, entrada, SHA-256`,"output.manifest":`metadatos exactos de lectura, huecos y descifrado`,"output.readme":`qué es la captura y cuáles son sus límites`,"output.keyFromDump":`La clave se recupera del propio volcado, así que no hace falta ningún archivo de claves ni ningún secreto del dispositivo.`,"output.bestEffort":`El descifrado sigue siendo un intento sin garantías. Si no se encuentra ninguna clave (por ejemplo, en una unidad cuyo bootloader deriva la clave de la OTP del chip, que no está en un volcado de la flash), esa ranura simplemente se omite y el resto del archivo no se ve afectado.`,"gap.summary":`El hueco de {address}`,"gap.where":"El conjunto de comandos USB ofrece un selector de ventana de lectura para cada bloque de 64 KB de la flash de 4 MB salvo `{range}`. Ese bloque se rellena con `{fill}` en la imagen combinada y se anota en `{manifest}`.","gap.costs":"**En la práctica, esto no te cuesta nada.** En la mayoría de las cámaras ese bloque es simplemente flash borrada, que se lee como `{fill}` de todos modos, así que el relleno coincide con lo que realmente hay y la imagen está completa.","gap.redundant":"Y cuando el bloque *sí* se usa, lo que contiene es una copia redundante. Estas cámaras guardan la misma imagen de firmware en varias ranuras de 64 KB: en todos los volcados con varias ranuras revisados al crear esta página, todas las ranuras se descifraron como un firmware idéntico byte a byte (en un caso, en cuatro ranuras escritas con dos claves distintas). En la única unidad vista con una imagen real en `{address}`, era idéntica byte a byte a las copias de `{before}` y `{after}`, así que el archivo sigue conteniendo ese firmware, solo que leído desde otra dirección.","gap.fine":"Esa redundancia es también la razón por la que una cámara cuyo `{address}` se lee como `{fill}` está bien: el firmware arrancable sigue existiendo en las otras ranuras. En cualquier caso, nada de esta pestaña escribe en el dispositivo: el hueco solo afecta al archivo que descargas.","gap.complete":`Si de verdad quieres una imagen estrictamente completa, byte a byte (por ejemplo, para compararla con una de referencia), léela por SWD/J-Link o con un programador SPI.`,"identity.versionUnknown":`Sin leer: la cámara no dijo qué firmware ejecuta.`,"identity.unsupported":`Sin leer: esta cámara no se puede leer de esta forma.`,"identity.title":`Cámara detectada`,"identity.firmware":`Firmware`,"identity.scoreBasis":`a partir de las respuestas de la cámara, antes de leer ninguna ranura`,"options.title":`Opciones`,"options.subtitle":`— los valores por defecto son correctos; no hace falta cambiar nada aquí.`,"options.chunk":`chunk (bytes control-IN)`,"options.gapFill":`byte gap-fill`,"options.retries":`reintentos por ventana`,"options.retryDelay":`espera entre reintentos (ms)`,"options.recipient":`recipient de la transferencia de control`,"options.recipientAuto":`auto`,"options.recipientInterface":`interface ({requestTypes})`,"options.recipientDevice":`device ({requestTypes})`,"options.decrypt":`descifrar firmware`,"options.yes":`sí`,"options.no":`no`,"options.help":`**chunk** es el tamaño de cada lectura control-IN, 64 como máximo: un paquete EP0. Una lectura más larga puede perder un paquete por culpa de la ROM de arranque de la cámara cuando la cámara está en reposo con el reloj bajo, así que un valor mayor se lee de 64 en 64 bytes; uno menor se usa tal cual, y si una cámara se atasca, la página baja el valor por su cuenta y continúa. **gap-fill** es el byte que se escribe en el único bloque de 64 KB al que USB no llega. **recipient** es interface por defecto y pasa a device si el navegador no puede reclamar la interfaz 0: el firmware acepta los dos.`,"options.chunkRange":`chunk debe estar entre 1 y {max}; se recibió {value}`,"options.gapFillByte":`gap-fill debe ser un solo byte; se recibió {value}`,"options.retriesMin":`los reintentos deben ser cero o más; se recibió {value}`,"options.retryDelayMin":`la espera entre reintentos debe ser cero o más; se recibió {value}`},slots:{"section.title":`Gestionar ranuras de firmware`,"section.badge":`Escribe en la flash`,"section.description":`«Leer ranuras» pregunta a la cámara qué ejecuta, lee sus tres ranuras de firmware ({a}, {b} y {r}) y muestra lo que contiene cada una. Leer y volcar no cambian nada. Los botones de escritura preguntan antes de enviar ningún byte.`,"section.danger":`**Esta página puede escribir en la flash de la cámara.** Una escritura borra una ranura de 64 KB y la programa. Una imagen con una estructura válida pero que no funciona deja la cámara sin poder arrancar, y el bootloader no tiene USB: solo SWD/J-Link o un programador SPI pueden recuperarla. Vuelca antes la ranura y guarda el archivo.`,"actions.toolbar":`Acciones de ranuras`,"actions.read":`Leer ranuras`,"run.label":`Ranuras`,"empty.connected":`Pulsa «Leer ranuras».`,"empty.disconnected":`Conecta la cámara y luego pulsa «Leer ranuras».`,"unsupported.title":`Esta compilación no se admite aquí, así que no se leyó ninguna ranura y no se puede escribir en ninguna.`,"refusal.notIdentified.title":`Sin identificar: esta página no puede saber qué compilación ejecuta la cámara.`,"refusal.notIdentified.body":`La cámara no dio ninguna versión de firmware utilizable, así que no se leyó ninguna ranura y no se abrió nada. Esta página cubre las compilaciones {minVersion} y posteriores. Las compilaciones anteriores a {minVersion} quedan fuera de lo que admite la página de ranuras, así que una cámara con una de ellas nunca se lee aquí.`,"refusal.notIdentified.hint":`Si la cámara ejecuta una compilación admitida, puede que solo esté arrancando. {hint}`,"refusal.title":`Rechazado: no se abrió nada.`,"status.reading":`Leyendo...`,"status.readingAgain":`Volviendo a leer las ranuras...`,"status.read":{one:`Leído. {read}/{count} ranura leída.`,many:`Leído. {read}/{count} de ranuras leídas.`,other:`Leído. {read}/{count} ranuras leídas.`},"status.unsupported":`No se admite en esta compilación: no se leyó ninguna ranura.`,"status.refused":`Rechazado: no se abrió nada. Consulta el mensaje debajo del registro.`,"status.disconnected":`Dispositivo desconectado: vuelve a leer las ranuras.`,"status.newDevice":`Nuevo dispositivo seleccionado: vuelve a leer las ranuras.`,"status.dumping":`Volcando {bank:acc}...`,"status.dumped":`Se volcó {bank:acc}.`,"status.readingImage":`Leyendo la imagen...`,"status.ready":`Listo: revisa el plan y luego escríbelo.`,"status.rejected":`Rechazado: consulta el registro de arriba.`,"status.writing":`Escribiendo...`,"status.patching":`Aplicando el parche {bank:dat}...`,"status.patchingEvery":`Aplicando el parche a todas las ranuras...`,"status.written.mismatch":`Escrito, pero la relectura no coincide: consulta el resultado.`,"status.written.verified":`Escrito. La ranura se relee tal como se escribió.`,"status.written.notCompared":`Escrito. La relectura no se comparó: consulta el resultado.`,"status.patched.unexpected":`Parche aplicado, pero la relectura no difiere solo según lo previsto: consulta el resultado.`,"status.patched.ok":`Parche aplicado. La ranura se relee según lo previsto.`,"status.patched.unchecked":`Parche aplicado. La relectura no se comprobó: consulta el resultado.`,"status.every.stopped":{one:`Detenido {bank:loc}: {count} ranura con el parche aplicado; consulta el resultado.`,many:`Detenido {bank:loc}: {count} de ranuras con el parche aplicado; consulta el resultado.`,other:`Detenido {bank:loc}: {count} ranuras con el parche aplicado; consulta el resultado.`},"status.every.unchecked":{one:`Se aplicó el parche a {count} ranura, pero una relectura no se comprobó según lo previsto: consulta el resultado.`,many:`Se aplicó el parche a {count} de ranuras, pero una relectura no se comprobó según lo previsto: consulta el resultado.`,other:`Se aplicó el parche a {count} ranuras, pero una relectura no se comprobó según lo previsto: consulta el resultado.`},"status.every.ok":{one:`Se aplicó el parche a {count} ranura. Se relee según lo previsto.`,many:`Se aplicó el parche a {count} de ranuras. Todas se releen según lo previsto.`,other:`Se aplicó el parche a {count} ranuras. Todas se releen según lo previsto.`},"status.cancelled.nothing":`Cancelado: no se escribió nada.`,"status.cancelled.one":`Cancelado después de enviar la confirmación de la escritura {bank:loc}: la ranura puede estar escrita en parte. Léela antes de contar con ella.`,"status.cancelled.many":`Cancelado después de enviar las confirmaciones de escritura {banks:loc}: cada una puede estar escrita en parte. Léelas antes de contar con ellas.`,"gate.connectFirst":`Primero conecta la cámara.`,"gate.busy":`Hay otra operación en curso: espera a que termine.`,"gate.readFirst":`Primero lee las ranuras.`,"gate.cameraRefused":`En esta cámara no se puede escribir desde aquí, por el motivo del aviso de arriba. No se envía nada.`,"gate.notRead":`Sin leer: {reason}. Vuelve a leer las ranuras antes de escribir en ella.`,"gate.notReadNoReason":`Sin leer: esta ranura no se leyó. Vuelve a leer las ranuras antes de escribir en ella.`,"gate.emptyNotWritable":`Esta ranura está vacía y no se puede escribir en esta compilación: {reason}`,"gate.noSuchBank":`Esta compilación no tiene esa ranura.`,"table.caption":`Cada ranura de firmware de esta cámara ({a}, {b} y {r}), tal como se leyó y comprobó en el navegador`,"table.col.bank":`Ranura`,"table.col.firmware":`Firmware`,"table.col.size":`Tamaño`,"table.col.key":`Clave`,"table.col.bootable":`Arrancable`,"table.col.sha":`SHA-256 sin cifrar`,"table.col.actions":`Acciones`,"table.notRead":`sin leer: {reason}`,"table.notReadNoReason":`sin leer: la ranura no se leyó`,"table.empty":`vacía`,"table.emptyNote":`Sin imagen: la ventana de cabecera de esta ranura se lee toda como 0xFF, así que no se descifra nada de ella, y escribir en ella no sobrescribe ningún firmware.`,"table.emptyWritable":`Se puede escribir.`,"table.emptyNotWritable":`No se puede escribir en esta compilación: {reason}`,"table.unknownVersion":`versión desconocida`,"table.imageId":`imagen {id}`,"table.noImage":`sin imagen`,"table.bankSize":`ranura de {size} B`,"table.imageSize":`imagen de {size} B`,"table.keyNone":`ninguna (sin cifrar)`,"table.boot.empty":`— nada que arrancar`,"table.boot.bootable":`arrancable: el bootloader la acepta`,"table.boot.notBootable":`no arrancable: se salta al arrancar`,"table.boot.recoveryOnly":`solo recuperación: {letterR} arranca cuando {letterA} y {letterB} no contienen nada que acepte el bootloader (medido en una cámara con una forma anterior de esta imagen); no se ha probado si esta forma arranca`,"table.boot.unknown":`desconocido: {why}`,"table.dump":`Volcar`,"table.flashPlain":`Escribir imagen descifrada…`,"table.flashRaw":`Escribir bytes sin procesar…`,"table.restore":`Restaurar desde copia de seguridad completa (.bin o .zip)…`,"table.makeFps":`Pasar a {hz} FPS`,"table.copyTo":`Copiar {bank:dat}`,"table.copyOff":`{button}: {reason}`,"table.copyOffNoReason":`{button}: desactivado`,"table.copyNote":`Copia el firmware que contiene esta ranura, tal como lo descifró esta lectura, en la ranura que elijas, contenga lo que contenga ahora. Revisas el plan antes de que se envíe nada.`,"table.restoreNote":`Elige una copia de seguridad completa de la flash: un .bin (una imagen completa de la flash de 4 MB, como una lectura con J-Link) o un .zip que contenga una (un archivo de ejecución de Preserve, o el zip que guarda «Volcar y descifrar 4.x/Nano» o «Volcar todos los selectores»). Esta ranura se extrae de ella, se descifra y se muestra como un plan antes de enviar nada.`,"table.fpsNote":`Sube esta ranura de {fromHz} Hz a {toHz} Hz editando sus bytes. Antes se guarda la ranura, en una descarga zip, y el archivo descifrado que contiene es la forma de volver atrás.`,"table.risk.bootedRecovery":`{booted} y ranura de recuperación: escribir en ella pide una confirmación adicional.`,"table.risk.booted":`{booted}: escribir en ella pide una confirmación adicional.`,"table.risk.recovery":`{bank}: escribir en ella pide una confirmación adicional.`,"table.risk.bootUnnamed":`La cámara no indica su ranura de arranque: escribir en ella pide una confirmación adicional.`,"fps.applied":`Parche de velocidad de fotogramas aplicado: esta imagen funciona a {hz} Hz.`,"fps.earlierPatch":`Parche de velocidad de fotogramas no disponible: esta ranura contiene un parche anterior de {hz} Hz sin la corrección de USB. Restaura la imagen de serie y luego usa «Pasar a {hz} FPS».`,"fps.atRate":`No hace falta parche de velocidad de fotogramas: esta compilación ya funciona a {hz} Hz.`,"fps.notOffered":`Parche de velocidad de fotogramas no disponible: {reason}`,"fps.readFirst":`primero lee las ranuras: el parche se planifica a partir de la propia imagen de la ranura`,"everyBank.toolbar":`Todas las ranuras`,"everyBank.make":`Pasar todas las ranuras a {hz} FPS`,"everyBank.faster":`Acelerar todas las ranuras`,"everyBank.note":`Aplica el parche {order:dat} con una sola confirmación; antes se guarda cada una, en una sola descarga zip, y después se relee.`,"everyBank.noteBootedLast":`Aplica el parche {order:dat} con una sola confirmación, y deja para el final la ranura desde la que arranca ahora la cámara; antes se guarda cada una, en una sola descarga zip, y después se relee.`,"what.copy":`la imagen {bank:gen}`,"what.restore":`{bank:acc} de {file}`,"preview.title":`Preparado para {bank:acc} en {address}`,"preview.file":`Archivo`,"preview.source":`Imagen tomada de`,"preview.target":`Destino`,"preview.targetEmpty":`{bank:ins} está vacía: no contiene ninguna imagen, así que esta escritura no sobrescribe ningún firmware`,"preview.readAs":`Leído como`,"preview.readAs.ff":`una imagen FF {version} descifrada`,"preview.readAs.plain":`una imagen descifrada`,"preview.readAs.raw":`bytes sin procesar`,"preview.staging":`Transferencia`,"preview.key":`Clave`,"preview.payload":`Datos`,"preview.payloadValue":{one:`{size} B en {count} bloque de hasta {chunk} B`,many:`{size} B en {count} de bloques de hasta {chunk} B`,other:`{size} B en {count} bloques de hasta {chunk} B`},"preview.checksum":`Suma de comprobación de la transferencia`,"preview.stored":`Almacenado después`,"preview.storedNotPredicted":`no predicho: la relectura es la comprobación`,"preview.storedPredicted":`{size} B predichos`,"preview.storedKeyB":`{size} B predichos: la imagen XOR la clave B, no los datos en sí`,"preview.savedFirst":`Guardado antes`,"preview.compareCaption":`Qué cambia {bank:loc}`,"preview.col.field":`Campo`,"preview.col.now":`Ahora`,"preview.col.after":`Tras la escritura`,"preview.readFirst":`Lee esto antes de escribir:`,"preview.note":`Nota: {note}`,"preview.nothingSent":`Aún no se ha enviado nada a la cámara. Al escribir, estos datos se envían {bank:dat} y se confirma la escritura.`,"preview.toolbar":`Acciones de escritura para {bank:acc}`,"preview.write":`Escribir {bank:loc}…`,"preview.discard":`Descartar`,"writeConfirm.title":`¿Escribir {what} {bank:loc} ({address})?`,"writeConfirm.booted":`{bootsNow}. Escribir en ella sustituye el firmware que la cámara está ejecutando ahora. Si la imagen nueva no funciona, puede que la cámara no arranque en absoluto.`,"writeConfirm.recovery":`{bank:ins} es la ranura de recuperación, la copia de último recurso a la que recurre el bootloader. Escribir en ella deja la cámara sin esa copia hasta que se restaure.`,"writeConfirm.bootUnnamed":`La cámara no dice desde qué ranura arranca, así que {bank:acc} se trata como la ranura desde la que arranca ahora. Escribir en ella puede sustituir el firmware que está ejecutando la cámara.`,"writeConfirm.empty":`{bank:ins} está vacía: no contiene ninguna imagen, así que no se sobrescribe ningún firmware.`,"writeConfirm.eraseEmpty":`La escritura borra igualmente el bloque de 64 KB de la flash de la cámara que ocupa {bank:acc} (ya en blanco) y lo programa.`,"writeConfirm.erase":`Esto borra un bloque de 64 KB de la flash de la cámara y lo programa {bank:loc}.`,"writeConfirm.keyLine":`La imagen se escribe con {key}. Todas las demás ranuras se escriben del mismo modo.`,"writeConfirm.backup":`Antes de enviar nada, se vuelve a leer {bank:acc} y se guarda como una descarga zip: {file}. Comprueba que está en tu carpeta de descargas.`,"writeConfirm.noReset":`No se envía ningún reinicio. Después, desconecta la cámara y vuelve a conectarla para que la ranura tenga efecto.`,"writeConfirm.noUsbRecovery":`Si la imagen no funciona, la cámara no se puede recuperar por USB: solo con SWD/J-Link o con un programador SPI.`,"writeConfirm.ackUnnamed":`Entiendo que la cámara no dice desde qué ranura arranca, así que esta se trata como la de arranque, y que una imagen defectuosa puede impedir que la cámara arranque.`,"writeConfirm.confirm":`Sí, escribir {bank:loc}`,"ack.booted":`Entiendo que esta es la ranura desde la que arranca ahora la cámara, y que una imagen defectuosa puede impedir que la cámara arranque.`,"ack.recovery":`Entiendo que esta es la ranura de recuperación, y que una imagen defectuosa deja la cámara sin una copia de último recurso.`,"fpsConfirm.title":`¿Hacer que {bank:acc} funcione a {hz} FPS?`,"fpsConfirm.booted":`{bootsNow}. La imagen con el parche sustituye el firmware que ejecuta ahora.`,"fpsConfirm.recovery":`{bank:ins} es la ranura de recuperación, la copia de último recurso a la que recurre el bootloader.`,"fpsConfirm.what":`{bank:ins} contiene el firmware {version}, y esto hace que su imagen funcione a {toHz} Hz en lugar de {fromHz} Hz.`,"fpsConfirm.unknownVersion":`(desconocida)`,"fpsConfirm.bytes":{one:`El parche cambia {count} byte de la imagen y la palabra de la suma de comprobación, para que se mantenga la suma que comprueba el bootloader. El par de claves no se toca.`,many:`El parche cambia {count} de bytes de la imagen y la palabra de la suma de comprobación, para que se mantenga la suma que comprueba el bootloader. El par de claves no se toca.`,other:`El parche cambia {count} bytes de la imagen y la palabra de la suma de comprobación, para que se mantenga la suma que comprueba el bootloader. El par de claves no se toca.`},"fpsConfirm.wayBack":`El archivo descifrado de ese zip es la forma de volver atrás: para deshacer el parche, escríbelo con «Escribir imagen descifrada» {bank:loc}.`,"fpsConfirm.noReset":`No se envía ningún reinicio. Después, desconecta la cámara y vuelve a conectarla para que la ranura con el parche tenga efecto.`,"fpsConfirm.ackUnnamed":`Entiendo que la cámara no dice desde qué ranura arranca, así que esta se trata como la de arranque.`,"fpsConfirm.confirm":`Sí, aplicar el parche {bank:dat}`,"fpsEvery.title":`¿Hacer que todas las ranuras funcionen a {hz} FPS?`,"fpsEvery.titleMixed":{one:`¿Aplicar el parche de velocidad de fotogramas a {count} ranura?`,many:`¿Aplicar el parche de velocidad de fotogramas a {count} de ranuras?`,other:`¿Aplicar el parche de velocidad de fotogramas a {count} ranuras?`},"fpsEvery.intro":{one:`Esto aplica el parche a {count} ranura en la que está disponible (firmware {version}):`,many:`Esto aplica el parche a {count} de ranuras en las que está disponible (firmware {version}):`,other:`Esto aplica el parche a {count} ranuras en las que está disponible (firmware {version}):`},"fpsEvery.role.bootedRecovery":`{bank} (la ranura desde la que arranca ahora esta cámara, y la ranura de recuperación)`,"fpsEvery.role.booted":`{bank} (la ranura desde la que arranca ahora esta cámara)`,"fpsEvery.role.recovery":`{bank} (la ranura de recuperación, la copia de último recurso)`,"fpsEvery.role.bootUnnamed":`{bank} (la cámara no dice desde qué ranura arranca)`,"fpsEvery.offer":{one:`{bank}: de {fromHz} Hz a {toHz} Hz, {count} byte y la palabra de la suma de comprobación.`,many:`{bank}: de {fromHz} Hz a {toHz} Hz, {count} de bytes y la palabra de la suma de comprobación.`,other:`{bank}: de {fromHz} Hz a {toHz} Hz, {count} bytes y la palabra de la suma de comprobación.`},"fpsEvery.other":`{bank}: {note}`,"fpsEvery.others":`Se quedan como están: {others}`,"fpsEvery.orderOne":`Escribe solo {bank:loc}, y luego la relee.`,"fpsEvery.order":`Se escriben en este orden: {order}. Cada una se relee antes de la siguiente, y el primer fallo detiene las demás.`,"fpsEvery.orderBootedLast":`Se escriben en este orden: {order}. La ranura desde la que arranca ahora la cámara va la última, así que, si algo falla, todo se detiene antes de llegar a ella. Cada una se relee antes de la siguiente, y el primer fallo detiene las demás.`,"fpsEvery.wayBack":`Los archivos descifrados de ese zip son la forma de volver atrás: para deshacer el parche de una ranura, escribe su archivo con «Escribir imagen descifrada» en esa ranura.`,"fpsEvery.noReset":`No se envía ningún reinicio. Después, desconecta la cámara y vuelve a conectarla para que las ranuras con el parche tengan efecto.`,"fpsEvery.ack":`Entiendo que esto escribe en estas ranuras, y que una imagen defectuosa puede impedir que la cámara arranque: {banks}.`,"fpsEvery.confirm":{one:`Sí, aplicar el parche a {count} ranura`,many:`Sí, aplicar el parche a {count} de ranuras`,other:`Sí, aplicar el parche a {count} ranuras`},"outcome.verified":`{bank} — {what}: la ranura se relee tal como se escribió.`,"outcome.mismatch":`{bank} — {what}: la relectura NO coincide con lo que se escribió.`,"outcome.notCompared":`{bank} — {what}: la relectura se hizo pero no se comparó, así que aquí esta escritura no está verificada.`,"outcome.commitStatus":`La confirmación de la cámara devolvió el estado {status}.`,"outcome.wasEmpty":`{bank:ins} estaba vacía antes de esta escritura, así que no se sobrescribió ningún firmware.`,"outcome.provenVerified":`Demostrado hasta ahora: los datos se enviaron y se confirmaron, y la ranura se relee tal como se escribió. NO demostrado: que el bootloader vaya a elegir esta ranura, ni que la imagen funcione.`,"outcome.provenCommitted":`Demostrado hasta ahora: los datos se enviaron y se confirmaron. NO demostrado: que el bootloader vaya a elegir esta ranura, ni que la imagen funcione.`,"outcome.replug":`**AHORA DESCONECTA LA CÁMARA Y VUELVE A CONECTARLA.** No se envió ningún reinicio, así que la ranura solo tiene efecto después de apagar y volver a encender la cámara de verdad. Luego vuelve a leer las ranuras: la versión y la ranura activa que indica la cámara son lo único que lo confirma.`,"outcome.replugShort":`**AHORA DESCONECTA LA CÁMARA Y VUELVE A CONECTARLA.** No se envió ningún reinicio. Luego vuelve a leer las ranuras.`,"outcome.savedFirst":`Guardado antes, como descarga: {file}.`,"outcome.wayBackOne":`El archivo descifrado que contiene es la forma de volver atrás («Escribir imagen descifrada» en la misma ranura).`,"outcome.wayBackMany":`Los archivos descifrados que contiene son la forma de volver atrás («Escribir imagen descifrada» en cada ranura).`,"outcome.checkDownloads":`Comprueba que está en tu carpeta de descargas.`,"fpsOutcome.title":`{bank} — parche aplicado de {fromHz} Hz a {toHz} Hz (firmware {version}).`,"fpsOutcome.readBackOk":{one:`La relectura solo difiere del volcado guardado en el {count} byte previsto, los puntos del parche y la palabra de la suma.`,many:`La relectura solo difiere del volcado guardado en los {count} de bytes previstos, los puntos del parche y la palabra de la suma.`,other:`La relectura solo difiere del volcado guardado en los {count} bytes previstos, los puntos del parche y la palabra de la suma.`},"fpsOutcome.readBackBad":{one:`La relectura NO difiere solo según lo previsto: {unexpected} bytes inesperados y {count} byte que falta.`,many:`La relectura NO difiere solo según lo previsto: {unexpected} bytes inesperados y {count} de bytes que faltan.`,other:`La relectura NO difiere solo según lo previsto: {unexpected} bytes inesperados y {count} bytes que faltan.`},"fpsOutcome.notTaken":`No se hizo la relectura, así que aquí el parche no está comprobado.`,"fpsEveryOutcome.title":{one:`Todas las ranuras: {done} de {count} con el parche aplicado, en este orden: {order}.`,many:`Todas las ranuras: {done} de {count} con el parche aplicado, en este orden: {order}.`,other:`Todas las ranuras: {done} de {count} con el parche aplicado, en este orden: {order}.`},"fpsEveryOutcome.readBackOk":{one:`La relectura solo difiere de la ranura guardada en el {count} byte previsto.`,many:`La relectura solo difiere de la ranura guardada en los {count} de bytes previstos.`,other:`La relectura solo difiere de la ranura guardada en los {count} bytes previstos.`},"fpsEveryOutcome.notTaken":`No se hizo la relectura.`,"fpsEveryOutcome.stopped":`Detenido: {reason}.`,"fpsEveryOutcome.notWritten":`Sin escribir: {banks}.`,"keys.refusedTitle":`Desde aquí no se puede escribir en ninguna ranura de esta cámara.`,"keys.title":`Claves de las escrituras`,"keys.chain":`Cadena`,"keys.chainPlain":`la cadena sin cifrar de 2014: todas las ranuras se almacenan sin cifrar, así que ninguna contiene una clave`,"keys.writtenAs":`Se escribe como`,"keys.writtenPlain":`la imagen tal cual, sin clave, en cualquier ranura`,"keys.stagedAs":`Se transfiere como`,"keys.storedAs":`Se almacena como`,"keys.refused":`Rechazado`,"keys.bootedBank":`Ranura de arranque`,"keys.bootedHolds":`{bank:ins} contiene {key:acc}`,"keys.theBootedBank":`la ranura de arranque`,"keys.unnamedKey":`una clave que la página no puede nombrar`,"keys.bootedBanksKey":`la clave de la ranura de arranque`,"keys.writtenDerived":`{line}; todas las ranuras se escriben del mismo modo`,"how.title":`Qué hacen estos botones`,"how.read":`**Leer ranuras** y **Volcar** no cambian nada en la cámara.`,"how.flash":`**Escribir imagen descifrada** toma una imagen sin cifrar, la cifra como necesita el firmware de esa ranura antes de transferirla y muestra el plan. **Escribir bytes sin procesar** transfiere el archivo exactamente como se da. Ninguno de los dos envía nada hasta que confirmas.`,"how.ff":`Escribir en {letterR} pide la confirmación adicional, como cualquier escritura en la ranura de recuperación. Una ranura **vacía** (su ventana de cabecera se lee toda como 0xFF, como {b:loc} de muchas cámaras de 2014) es un estado, no un fallo. Se escribe exactamente igual que cualquier otra ranura.`,"how.copy":`**Restaurar desde copia de seguridad completa** toma un .bin (una imagen completa de la flash de 4 MB, como una lectura con J-Link) o un .zip que contenga una (un archivo de ejecución de Preserve, o el zip que guarda «Volcar y descifrar 4.x/Nano» o «Volcar todos los selectores»), extrae de él esta ranura, la descifra y muestra el plan; si la copia parece de otra cámara o de otro firmware, el plan lo dice.`,"how.fps":`**Pasar a N FPS** en la fila de una ranura edita la imagen de esa ranura para una velocidad de fotogramas más alta, y **Pasar todas las ranuras a N FPS** lo hace en todas las ranuras en las que el parche está disponible, con una sola confirmación, y deja para el final la ranura desde la que arranca ahora la cámara. Para una ranura en la que no está disponible, la página dice por qué.`,"how.backup":"**Cada escritura guarda antes su ranura**: la ranura se vuelve a leer y se guarda como una descarga zip, con un nombre que lleva la hora, el número de serie de la cámara, el firmware, la ranura y la escritura (por ejemplo, `{example}`), y que contiene la ranura tal como está almacenada, su imagen descifrada y una nota de lo que es cada archivo. Para volver atrás, escribe el archivo descifrado del zip con **Escribir imagen descifrada**.","how.write":"Una escritura borra una ranura de 64 KB y la programa. El bootloader en `{address}` y la configuración de arranque nunca se escriben aquí, y no hay ningún control para elegir la ranura activa. La ranura solo tiene efecto después de desconectar la cámara y volver a conectarla."},preserve:{"how.title":`Qué esperar`,"how.descriptionIdle":`Conecta la cámara y empieza por el paso 02.`,"how.descriptionRun":`Ejecución {runId}.`,"how.descriptionRunVersion":`Ejecución {runId}: firmware {version}.`,"how.restarts":`La cámara **se reinicia** durante cada paso. Tras un reinicio, Chrome ya no la reconoce (no tiene número de serie USB), así que la página te pide que pulses **Conectar dispositivo** y vuelvas a elegir la cámara. Es el funcionamiento normal: el paso continúa solo en cuanto lo haces.`,"how.noFile":`No hay que elegir ningún archivo de firmware: todo se lee de la propia cámara.`,"how.banks":`La cámara guarda su firmware en tres **ranuras** ({a}, {b} y {r}). El paso 02 lee las tres y averigua desde cuál arrancará la cámara la próxima vez; el parche solo funciona si esa ranura lo contiene. Tú eliges las ranuras a las que el paso 03 aplica el parche (por defecto, la del próximo arranque), y el paso 04 las vuelve a poner todas como estaban.`,"how.runFile":"Después de cada paso, tu navegador descarga un **archivo de ejecución** con un nombre que lleva el inicio de la ejecución, la hora de guardado y el paso al que llegó (`{example}`), con una carpeta por paso dentro. Guarda el más reciente: te permite continuar más tarde.","how.writeWarning":`**Los pasos 03 y 04 escriben en la flash de la cámara**, y cada uno te pide confirmación antes. Mientras se ejecuta uno de ellos, mantén la cámara conectada (salvo que la página te pida desconectarla y volver a conectarla) y el equipo despierto, mejor enchufado a la corriente. Una escritura interrumpida deja una cámara que solo un programador de hardware (SPI o SWD/J-Link) puede arreglar.`,"how.phone":`**En un teléfono:** antes del paso 03, activa el modo avión y desactiva el wifi y los datos móviles, para que una llamada o una notificación no aparte al navegador a mitad de una escritura, y mantén la pantalla encendida. Una vez abierta, la página sigue funcionando sin conexión.`,"how.pastCommit":`**La escritura no consta en el registro de esta ejecución, así que los pasos que la siguen están bloqueados.** Puede que la cámara ya esté ejecutando la imagen con el parche (una escritura interrumpida) o puede que no (la escritura nunca empezó): el archivo de ejecución no puede demostrar cuál de las dos. No ejecutes la lectura completa ni la restauración en una cámara con el parche sin que la escritura conste en el registro; el camino a seguir es el paso 03, cuya comprobación previa a la escritura lee la ranura y se niega a volver a escribirla a ciegas. Solo si esa comprobación ya se ha negado con *already holds the patched bytes* se aplica el salto, y pasa por su propio diálogo.`,"phase.readBuild.label":`Lectura y preparación`,"phase.readBuild.inSentence":`la lectura y preparación`,"phase.readBuild.description":`Lee todo lo que deja leer una cámara de serie (31 bloques de 64 KB) y lo guarda como tu copia de seguridad, lee cada ranura de firmware una segunda vez, averigua desde qué ranura arrancará la cámara la próxima vez y prepara el pequeño parche que escribe el paso siguiente. No se escribe nada en la cámara. Normalmente tarda menos de un minuto. Si la cámara necesita reiniciarse por el camino, la página te pide que pulses «Conectar dispositivo» y vuelvas a elegirla: es lo esperado.`,"phase.patchDump.label":`Escritura y lectura completa`,"phase.patchDump.inSentence":`la escritura y lectura completa`,"phase.patchDump.description":`Escribe un parche pequeño y temporal en las ranuras de firmware elegidas en el paso 02 (por defecto, la ranura desde la que arrancará la cámara la próxima vez), para que pueda leer toda su flash. Luego la cámara se reinicia (pulsa «Conectar dispositivo» y vuelve a elegirla cuando la página lo pida) y se lee toda la flash de 4 MB. El paso 04 vuelve a poner el firmware original.`,"phase.restoreVerify.label":`Restauración y verificación`,"phase.restoreVerify.inSentence":`la restauración y verificación`,"phase.restoreVerify.description":`Vuelve a escribir tu firmware original, reinicia la cámara (pulsa «Conectar dispositivo» y vuelve a elegirla cuando se te pida) y luego lo vuelve a leer todo para comprobar que coincide byte a byte con la copia de seguridad.`,"step.backup.description":`Lee los 31 bloques de 64 KB que puede leer una cámara de serie, luego lee cada ranura una segunda vez (las dos lecturas deben coincidir byte a byte), extrae el firmware de cada ranura a partir de lo que almacena la cámara (descifrado donde está cifrado) y lo comprueba, y averigua desde qué ranura arrancará la cámara la próxima vez. Esta es la única copia de esta cámara que tiene la ejecución, hecha antes de escribir nada.`,"step.patch.description":`Sin conexión, sin cámara. Prepara el parche para cada ranura que puede escribir la ejecución: permite que la lectura de la cámara llegue a toda la flash de 4 MB, y se escribe en la forma en que la cámara lo almacena, así que solo cambian los bytes del propio parche.`,"step.commit.description":`La escritura. Primero vuelve a leer cada ranura elegida y no escribe nada salvo que cada una siga conteniendo lo que registró la copia de seguridad (una escritura que ya se completó nunca se repite); luego escribe cada una, dejando para el final la ranura que la cámara prueba primero. Aquí no se reinicia la cámara: la reinicia el paso siguiente.`,"step.drain.description":`Reinicia la cámara para que arranque el firmware con el parche (queda en silencio unos diez segundos; la página espera y la vuelve a encontrar), comprueba desde qué ranura arrancó (una ranura sin el parche detiene el paso antes de leer nada), luego lee toda la flash de 4 MB en una sola lectura y pone en la imagen guardada el firmware original de cada ranura escrita, sacado de la copia de seguridad. No se escribe nada.`,"step.restore.description":`La otra escritura. Vuelve a escribir el firmware original de cada ranura escrita mientras sigue funcionando el firmware con el parche, y luego reinicia la cámara.`,"step.verify.description":`Después de un arranque nuevo, vuelve a leer los 31 bloques, con todas las ranuras entre ellos: 0 bytes distintos demuestra que la flash de la cámara es idéntica byte a byte a la copia de seguridad. Solo lectura.`,"phase.start":`Iniciar {phase}`,"phase.retry":`Reintentar {phase}`,"phase.goRestore":`Seguir con el paso 04: restaurar las ranuras`,"phase.jumpOnly":`Saltar la escritura no registrada`,"phase.skipWrite":`Saltar la escritura: empezar por la lectura completa`,"phase.toolbar":`{phase}: acciones`,"badge.writes":`escribe en la cámara`,"badge.running":`En curso`,"badge.done":`Hecho`,"badge.plannedStop":`Detenido según lo previsto: ahora toca la restauración`,"badge.failed":`Detenido: consulta el registro`,"badge.upNext":`Siguiente`,"notReady.noRun":`Disponible después del paso 02, que inicia la ejecución.`,"notReady.previous":`Disponible después del paso {step} ({phase}).`,"notReady.gate":`Aún no está listo: {reason}.`,"phase.pastCommit":`Afecta a la cámara con el parche mientras la escritura no conste en el registro: puede que la cámara ya tenga el parche. Consulta la nota de «{section}».`,"phase.noDrain":`La lectura completa no se ha ejecutado: este paso deja la cámara como estaba sin ella. Ejecuta antes el paso 03, salvo que la lectura completa no te importe.`,"phase.keepPlugged":`Mantén la cámara conectada y el equipo despierto hasta que termine este paso.`,"phase.stepsLabel":`Progreso`,"phase.showDetails":`Mostrar detalles en el registro`,"phase.inDetail":`Qué hace este paso, en detalle`,"yourTurn.toolbar":`Te toca`,"yourTurn.reconnect.title":`Te toca: pulsa «Conectar dispositivo» y elige la cámara.`,"yourTurn.reconnect.body":`La cámara se ha reiniciado, como estaba previsto. Chrome no puede volver a reconocerla por sí solo (no tiene número de serie USB), así que necesita que la elijas otra vez. El paso continúa en cuanto lo hagas.`,"yourTurn.replug.title":`Te toca: desconecta la cámara, vuelve a conectarla y luego pulsa «Conectar dispositivo».`,"yourTurn.replug.body":`El parche de esta ejecución se hizo antes de la corrección del lector, así que la cámara necesita un encendido nuevo antes de la restauración. El archivo de ejecución ya está guardado.`,"yourTurn.replugBeforeRestore.title":`Antes del paso 04: desconecta la cámara, vuelve a conectarla y luego pulsa «Conectar dispositivo».`,"yourTurn.powerCycle.title":`Te toca: desconecta la cámara, vuelve a conectarla, pulsa «Conectar dispositivo» y luego vuelve a intentarlo.`,"yourTurn.powerCycle.body":`El lector de la cámara necesita un encendido nuevo antes de poder volver a leerla. La ejecución sigue cargada aquí; no se pierde nada.`,"yourTurn.powerCycleAssert.title":`Te toca: desconecta la cámara, vuelve a conectarla, pulsa «Conectar dispositivo» y luego continúa.`,"yourTurn.powerCycleAssert.body":`El último intento de copia de seguridad se detuvo, y la cámara necesita un encendido nuevo antes de volver a ejecutarlo. La cámara no puede indicarlo por sí misma, así que el botón de abajo le dice a la página que lo has hecho.`,"yourTurn.replugged":`Ya la he vuelto a conectar: continuar con {phase}`,"banks.title":`A qué ranuras aplica el parche el paso 03`,"banks.bootWord":`Palabra de configuración de arranque`,"banks.lastStart":`Último arranque`,"banks.nextStart":`Próximo arranque`,"banks.caption":`Las tres ranuras de firmware, tal como las leyó el paso 02`,"banks.col.bank":`Ranura`,"banks.col.address":`Dirección`,"banks.col.holds":`Qué contiene`,"banks.nextStartBadge":`próximo arranque`,"banks.choiceLabel":`Ranuras a las que aplicar el parche`,"choice.nextStart":`La ranura del próximo arranque`,"choice.all":`Todas las ranuras`,"choice.withBanks":`{choice} — {banks}`,"choice.notOffered":`{choice} — no disponible`,"banks.notChosen":`Aún no se ha elegido ninguna ranura: {what}. Elige una ranura por su nombre arriba.`,"banks.writes":`El paso 03 escribe {what}.`,"banks.fixed":`La escritura ya se ha ejecutado, así que la elección es fija: el paso 04 vuelve a poner exactamente estas ranuras.`,"banks.notOfferedLine":`{choice}: no disponible — {why}.`,"banks.refusedNoRun":`no hay ninguna ejecución activa: el paso 02 inicia una`,"banks.refusedBusy":`hay un paso en curso: elige las ranuras cuando haya terminado`,"plan.summary":`El plan — {build}, aplica el parche {banks:dat}`,"plan.summaryNone":`El plan — {build}, aún no se ha elegido ninguna ranura`,"plan.yourCamera":`tu cámara`,"plan.intro":`Sacado de los propios bytes de la cámara. No se escribe nada hasta que se ejecuta el paso 03, y el paso 04 vuelve a poner cada byte que escribe.`,"plan.build":`Compilación`,"plan.version":`Versión de firmware`,"plan.written":`Escrito`,"plan.route":`Dónde va`,"plan.restore":`Restauración`,"plan.wholeFlash":`Lectura completa`,"plan.outro":`En la forma en que almacena la cámara, cambian los mismos bytes y ningún otro, así que el firmware de la cámara cambia exactamente en esta diferencia y en nada más.`,"bankPlan.label":`El parche {bank:gen}`,"bankPlan.titleChosen":`{bank} — la escribe esta ejecución`,"bankPlan.titleNotChosen":`{bank} — no elegida`,"bankPlan.source":`Origen de la imagen`,"bankPlan.sourceValue":`{bank}, tal como está almacenada`,"bankPlan.sourceTwoReads":`{bank}, tal como está almacenada, dos lecturas coincidentes (sha256 {sha})`,"bankPlan.edit":`Cambio en la imagen`,"bankPlan.editValue":`{label} ({id}) sobre la imagen de fábrica. Su compensación, {balance}, está en la palabra de ajuste; el parche compensa por encima de ella, y el paso 04 vuelve a poner la imagen con el cambio.`,"bankPlan.factorySha":`sha256 sin cifrar de fábrica`,"bankPlan.patchedSha":`sha256 con el parche`,"bankPlan.diffCount":`Bytes cambiados en el chip de flash`,"bankPlan.staged":`Longitud transferida`,"bankPlan.stagedValue":{one:`{size} B en {count} bloque`,many:`{size} B en {count} de bloques`,other:`{size} B en {count} bloques`},"bankPlan.rebalance":`Palabra de compensación`,"bankPlan.rebalanceValue":`{word} (antes {balance}, la compensación del cambio)`,"bankPlan.caption":`Los bytes exactos que mueve el parche {bank:loc}`,"bankPlan.col.what":`Qué cambia`,"bankPlan.col.offset":`Desplazamiento`,"bankPlan.col.before":`Antes`,"bankPlan.col.after":`Después`,"verify.ok":{one:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} byte distinto. Su flash está exactamente como antes de la primera escritura.`,many:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} de bytes distintos. Su flash está exactamente como antes de la primera escritura.`,other:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} bytes distintos. Su flash está exactamente como antes de la primera escritura.`},"verify.okShort":{one:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} byte distinto (bloques cortos: {blocks}). Su flash está exactamente como antes de la primera escritura.`,many:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} de bytes distintos (bloques cortos: {blocks}). Su flash está exactamente como antes de la primera escritura.`,other:`**Verificado: coincidencia perfecta.** Tras un arranque nuevo se volvió a leer la cámara: {read}/31 bloques, {count} bytes distintos (bloques cortos: {blocks}). Su flash está exactamente como antes de la primera escritura.`},"verify.failed":`**La comprobación encontró diferencias con la copia de seguridad.** {error}`,unknownReason:`motivo desconocido`,"confirm.titleWrite":`{phase}: ¿escribir en {banks:acc}?`,"confirm.titleJump":`{phase}: ¿saltar la escritura no registrada?`,"confirm.chosenBanks":`las ranuras elegidas`,"confirm.jump":`LA ESCRITURA NO CONSTA EN EL REGISTRO de esta ejecución, y estás afirmando que las escrituras se completaron sin sus puntos de control: el paso empieza después de la escritura en lugar de volver a escribir. Las comprobaciones propias de los pasos se siguen haciendo (la lectura de la versión, las comprobaciones de las ranuras), y una suposición equivocada cuesta una lectura completa perdida, no una cámara inutilizada.`,"confirm.jumpKeepPlugged":`Mantén la cámara conectada y el equipo despierto hasta que termine el paso.`,"confirm.patch":`Esto escribe un pequeño parche en {banks:acc}. El paso 04 vuelve a poner los originales. La lectura completa que viene después solo lee.`,"confirm.patchInOrder":`Esto escribe un pequeño parche en {banks:acc}, en ese orden: la ranura que la cámara prueba primero va la última. El paso 04 vuelve a poner los originales. La lectura completa que viene después solo lee.`,"confirm.restore":`Esto vuelve a escribir tu firmware original en {banks:acc}.`,"confirm.restoreInOrder":`Esto vuelve a escribir tu firmware original en {banks:acc}, en ese orden: la ranura que la cámara prueba primero va la primera.`,"confirm.keepPlugged":`Mantén la cámara conectada y el equipo despierto mientras escribe: una escritura interrumpida deja una cámara que solo un programador de hardware (SPI o SWD/J-Link) puede arreglar. En un teléfono, con el modo avión activado y la pantalla siempre encendida. Después la cámara se reinicia; cuando la página lo pida, pulsa «Conectar dispositivo» y vuelve a elegirla. Es lo esperado.`,"confirm.yesJump":`Sí, saltar la escritura`,"confirm.yesWrite":`Sí, escribir en la cámara`,"summary.proof":`La prueba`,"summary.complete":`Imagen completa (4 MB)`,"summary.notProduced":`no generado`,"summary.differs":{one:`difiere de la copia de seguridad en {differing} de {count} bloque: {blocks}`,many:`difiere de la copia de seguridad en {differing} de {count} de bloques: {blocks}`,other:`difiere de la copia de seguridad en {differing} de {count} bloques: {blocks}`},"summary.matches":{one:`coincide con la copia de seguridad ({count} bloque)`,many:`coincide con la copia de seguridad (los {count} de bloques)`,other:`coincide con la copia de seguridad (los {count} bloques)`},"summary.onlyInFull":`Solo en la lectura completa`,"summary.onlyInFullValue":{one:`{count} bloque al que no llega una lectura de serie: {blocks}`,many:`{count} de bloques a los que no llega una lectura de serie: {blocks}`,other:`{count} bloques a los que no llega una lectura de serie: {blocks}`},"summary.rawDump":`Lectura completa, tal como se leyó`,"summary.rawDumpBadge":`lo mismo, con el parche aún dentro`,"summary.image":`Imagen de firmware (descifrada, {bank})`,"summary.verify":`Verificación`,"summary.toolbar":`Acciones del archivo`,"summary.download":`Descargar el archivo completo (archivo de ejecución)`,"output.title":`Lo que obtienes`,"output.intro":"El archivo de ejecución es una sola descarga `{ext}`. Cada guardado contiene todo lo que la ejecución ha generado hasta ese momento, con una carpeta por paso:","output.caption":`Archivos dentro del archivo de ejecución`,"output.file":`Archivo`,"output.what":`Qué es`,"output.runState":`el registro de la ejecución: carga el zip en esta pestaña para continuar la ejecución o para volver a verla`,"output.readme":`qué hay en el zip y dónde`,"output.backup":`tu copia de seguridad: los 31 bloques que deja leer una cámara de serie, leídos antes de escribir nada, cada uno en su dirección de la flash ({fill} donde un bloque no se puede leer así)`,"output.capture":`cada ranura de firmware que la ejecución puede escribir, tal como la guarda la cámara (a, b o r en el nombre), leída dos veces con las dos lecturas iguales`,"output.plain":`el firmware de cada una de esas ranuras, descifrado`,"output.patched":`para cada ranura que parchea la ejecución: su firmware con el parche temporal de lectura`,"output.decrypted":`la copia de seguridad descifrada: el firmware de cada ranura y un informe sobre él`,"output.manifest":`los detalles de ese descifrado`,"output.decryptReadme":`qué contiene ese descifrado y cuáles son sus límites`,"output.pageBuild":`qué compilación de esta página hizo la ejecución`,"output.dumpPatched":`los 4 MB completos tal como se leyeron, con el parche aún en las ranuras donde se escribió`,"output.dumpOriginal":`la imagen completa: los 4 MB enteros con el firmware original de vuelta en su sitio; la flash original de tu cámara`,"output.verify":`los 31 bloques leídos de nuevo tras la restauración, ordenados como la copia de seguridad; deberían coincidir con ella`,"output.grows":`Cada archivo aparece cuando se ha ejecutado el paso que lo genera, así que un archivo de ejecución temprano solo contiene la primera carpeta.`,"output.keep":"El archivo que debes conservar es `{original}`: toda la flash de tu cámara tal como estaba. El resto muestra cómo llegó ahí la ejecución.","runFile.eyebrow":`Opcional: para continuar una ejecución más tarde`,"runFile.title":`Archivo de ejecución`,"runFile.description":`El único registro de la ejecución. Se descarga solo después de cada paso (y después de un paso que se detuvo antes de tiempo); guarda el más reciente. Para continuar más tarde, o después de un problema, cárgalo aquí y la página sigue donde lo dejó.`,"runFile.run":`Ejecución`,"runFile.file":`Archivo`,"runFile.lastSaved":`Último guardado`,"runFile.lastSavedValue":`después de {step} — {at} ({bytes} B)`,"runFile.nextStep":`Paso siguiente`,"runFile.none":`No hay ninguna ejecución activa. El paso 02 inicia una, o carga aquí un archivo de ejecución.`,"runFile.toolbar":`Acciones del archivo de ejecución`,"runFile.load":`Cargar un archivo de ejecución…`,"runFile.save":`Volver a guardar el archivo de ejecución`,"runFile.panel":`Reanudar`,"status.noFile":`No se ha elegido ningún archivo de ejecución.`,"status.notRun":`Aún no se ha ejecutado.`,"status.running":`En curso…`,"status.runningRestarts":`En curso: la cámara se reinicia durante este paso…`,"status.restarting":`La cámara se está reiniciando: tarda unos diez segundos…`,"status.waitConnect":`Esperándote: pulsa «Conectar dispositivo» y elige la cámara…`,"status.waitPlugBack":`Esperándote: vuelve a conectar la cámara y luego pulsa «Conectar dispositivo»…`,"status.waitReplug":`Esperándote: desconecta la cámara y vuelve a conectarla…`,"status.back":`La cámara ha vuelto: continuando…`,"status.swapped":`Detenido: la cámara ha cambiado. Compruébala y luego vuelve a ejecutar la fase.`,"status.noRun":`Sin ejecución.`,"status.notCreated":`No se creó: consulta el registro de arriba.`,"status.refused":`Rechazado: la lista de fases de arriba dice qué falta.`,"status.done":`{phase}: hecho. El archivo de ejecución de tus descargas está al día.`,"status.doneReplug":`{phase}: hecho, y el archivo de ejecución está guardado. Antes de la restauración: desconecta la cámara, vuelve a conectarla y pulsa «Conectar dispositivo».`,"status.backupRefused":`Rechazado: no se escribió nada. Consulta el registro de arriba.`,"status.failed":`Error: consulta el registro de arriba.`,"status.cancelled":`Cancelado: el archivo de ejecución sigue indicando dónde se detuvo la ejecución.`,"status.readingFile":`Leyendo el archivo de ejecución…`,"status.doneEarlier":`Hecho antes: cargado desde el archivo de ejecución.`,"status.failedEarlier":`Falló antes: {error}`,"status.resumed":`Reanudado en {step}. La lista de fases continúa desde ahí.`,"status.notResumed":`No se reanudó: consulta el registro de arriba.`,"gate.needs":`hace falta {missing}`,"gate.noRun":`no hay ninguna ejecución activa: la primera fase crea la ejecución`,"gate.runDone":`esta ejecución ha terminado: se completaron todas las fases`,"gate.alreadyDone":`ya está hecho: al reanudar, se continúa en {step}`,"gate.banksRead":`las ranuras que lee la copia de seguridad`,"gate.choice":`una elección de ranuras — {why}`,"gate.bankRefused":`no se puede escribir {bank:loc}: {reason}`,"gate.recoveryRoute":`la vía de la ranura de recuperación (esta compilación solo arranca desde {r:acc}, no desde {bank:acc})`,"gate.backupFirst":`la copia de seguridad de la flash (se ejecuta primero en esta fase)`,"gate.backup":`la copia de seguridad de la flash`,"gate.patchStep":`el paso «Parche»`,"gate.patchOf":`el parche {bank:gen}`,"gate.backupFile":`el archivo de ventanas de la copia de seguridad`,"gate.capture":`la captura {bank:gen}`,"gate.derived":`la imagen derivada {bank:gen}`,"gate.writeStep":`el paso «Escritura» (ejecútalo o reanuda en él primero)`,"gate.drainRefused":`la lectura completa se niega en {build}: {why}`,"gate.patchSummary":`el resumen del parche {bank:gen} (la longitud transferida)`,"gate.restoreRefused":`la restauración se niega en {build}: ninguna forma del firmware original se vuelve a almacenar como los bytes originales; la ejecución termina con la imagen completa y con el parche puesto`,"gate.plaintext":`el firmware de fábrica sin cifrar {bank:gen} ({file}, del paso de copia de seguridad)`,"gate.restoreFirst":`la restauración (se ejecuta primero en esta fase)`,"gate.powerCycle":`la confirmación del apagado y encendido: apaga la cámara y vuelve a encenderla (desconéctala y vuelve a conectarla, o usa su interruptor) y luego usa el control para volver a ejecutar`,"error.cameraNotBack":`la cámara no volvió después de {minutes} min de reintentos: {error}. Si Chrome no preguntó nada, desconecta la cámara, vuelve a conectarla y vuelve a ejecutar la fase; si el registro decía que la volvieras a conectar, lo que esperaba era el clic en «Conectar dispositivo»`}};export{e as default};
